#define M33C1SPGSS2_UC1_SPI_IPSPECIFIC_CLKCTL_SCR_OFS (0)                             /* !< SCR Offset */
#define M33C1SPGSS2_UC1_SPI_IPSPECIFIC_CLKCTL_SCR_MASK ((uint32_t)0x000003FFU)         /* !< Serial clock divider: This is used
                                                                                    to generate the transmit and receive
                                                                                    bit rate of the SPI. The SPI bit rate
                                                                                    is (SPI's functional clock
                                                                                    frequency)/((SCR+1)*2). SCR is a
                                                                                    value from 0-1023. */
#define M33C1SPGSS2_UC1_SPI_IPSPECIFIC_CLKCTL_SCR_MINIMUM ((uint32_t)0x00000000U)         /* !< Smallest value */
#define M33C1SPGSS2_UC1_SPI_IPSPECIFIC_CLKCTL_SCR_MAXIMUM ((uint32_t)0x000003FFU)         /* !< Highest possible value */
