#define M33C1SPGSS2_UC0_SPI_IPSPECIFIC_CTL0_SPO_MASK ((uint32_t)0x00000100U)         /* !< CLKOUT polarity (Motorola SPI frame
                                                                                    format only) */
#define M33C1SPGSS2_UC0_SPI_IPSPECIFIC_CTL0_SPO_LOW ((uint32_t)0x00000000U)         /* !< SPI produces a steady state LOW
                                                                                    value on the CLKOUT */
#define M33C1SPGSS2_UC0_SPI_IPSPECIFIC_CTL0_SPO_HIGH ((uint32_t)0x00000100U)         /* !< SPI produces a steady state HIGH
                                                                                    value on the CLKOUT */
/* M33C1SPGSS2_UC0_SPI_IPSPECIFIC_CTL0[SPH] Bits */
#define M33C1SPGSS2_UC0_SPI_IPSPECIFIC_CTL0_SPH_OFS (9)                             /* !< SPH Offset */
#define M33C1SPGSS2_UC0_SPI_IPSPECIFIC_CTL0_SPH_MASK ((uint32_t)0x00000200U)         /* !< CLKOUT phase (Motorola SPI frame
                                                                                    format only) This bit selects the
                                                                                    clock edge that captures data and
                                                                                    enables it to change state. It has
                                                                                    the most impact on the first bit
                                                                                    transmitted by either permitting or
                                                                                    not permitting a clock transition
                                                                                    before the first data capture edge. */
#define M33C1SPGSS2_UC0_SPI_IPSPECIFIC_CTL0_SPH_FIRST ((uint32_t)0x00000000U)         /* !< Data is captured on the first clock
                                                                                    edge transition. */
#define M33C1SPGSS2_UC0_SPI_IPSPECIFIC_CTL0_SPH_SECOND ((uint32_t)0x00000200U)         /* !< Data is captured on the second
                                                                                    clock edge transition. */
/* M33C1SPGSS2_UC0_SPI_IPSPECIFIC_CTL0[CSCLR] Bits */
#define M33C1SPGSS2_UC0_SPI_IPSPECIFIC_CTL0_CSCLR_OFS (14)                            /* !< CSCLR Offset */
#define M33C1SPGSS2_UC0_SPI_IPSPECIFIC_CTL0_CSCLR_MASK ((uint32_t)0x00004000U)         /* !< Clear shift register counter on CS
                                                                                    inactive This bit is relevant only in
                                                                                    the peripheral, CTL1.CP=0. */
#define M33C1SPGSS2_UC0_SPI_IPSPECIFIC_CTL0_CSCLR_DISABLE ((uint32_t)0x00000000U)         /* !< Disable automatic clear of shift
                                                                                    register when CS goes to disable. */
#define M33C1SPGSS2_UC0_SPI_IPSPECIFIC_CTL0_CSCLR_ENABLE ((uint32_t)0x00004000U)         /* !< Enable automatic clear of shift
                                                                                    register when CS goes to disable. */

/* M33C1SPGSS2_UC0_SPI_IPSPECIFIC_STAT Bits */
/* M33C1SPGSS2_UC0_SPI_IPSPECIFIC_STAT[TXFE] Bits */
#define M33C1SPGSS2_UC0_SPI_IPSPECIFIC_STAT_TXFE_OFS (5)                             /* !< TXFE Offset */
#define M33C1SPGSS2_UC0_SPI_IPSPECIFIC_STAT_TXFE_MASK ((uint32_t)0x00000020U)         /* !< Transmit FIFO empty. */
