#define M33C1SPGSS2_UC0_SPI_IPSPECIFIC_STAT_RXFE_MASK ((uint32_t)0x00000004U)         /* !< Receive FIFO empty. */
#define M33C1SPGSS2_UC0_SPI_IPSPECIFIC_STAT_RXFE_NOT_EMPTY ((uint32_t)0x00000000U)         /* !< Receive FIFO is not empty. */
#define M33C1SPGSS2_UC0_SPI_IPSPECIFIC_STAT_RXFE_EMPTY ((uint32_t)0x00000004U)         /* !< Receive FIFO is empty. */
