#define M33C1SPGSS2_UC0_SPI_IPSPECIFIC_STAT_BUSY_OFS (8)                             /* !< BUSY Offset */
#define M33C1SPGSS2_UC0_SPI_IPSPECIFIC_STAT_BUSY_MASK ((uint32_t)0x00000100U)         /* !< Busy */
#define M33C1SPGSS2_UC0_SPI_IPSPECIFIC_STAT_BUSY_IDLE ((uint32_t)0x00000000U)         /* !< SPI is in idle mode. */
#define M33C1SPGSS2_UC0_SPI_IPSPECIFIC_STAT_BUSY_ACTIVE ((uint32_t)0x00000100U)         /* !< SPI is currently transmitting
                                                                                    and/or receiving data */
