#define M33C1SPGSS2_UC0_SPI_IPSPECIFIC_CTL1_POD_ENABLE ((uint32_t)0x00000008U)         /* !< SPI cannot drive the POCI output in
                                                                                    peripheral mode. */
/* M33C1SPGSS2_UC0_SPI_IPSPECIFIC_CTL1[MSB] Bits */
#define M33C1SPGSS2_UC0_SPI_IPSPECIFIC_CTL1_MSB_OFS (4)                             /* !< MSB Offset */
