#define M33C1SPGSS2_UC3_I2CT_IPSPECIFIC_CTR_EN_ALRESPADR_DISABLE ((uint32_t)0x00000000U)         /* !< When this bit is 0, the alert
                                                                                    response address is not matched.
                                                                                    NOTE: it may still be matched if
                                                                                    programmed inside SOAR/SOAR2 */
#define M33C1SPGSS2_UC3_I2CT_IPSPECIFIC_CTR_EN_ALRESPADR_ENABLE ((uint32_t)0x00000100U)         /* !< When this bit is 1, alert response
                                                                                    address of 7h000_1100 is always
                                                                                    matched by the Target address match
                                                                                    logic. */
/* M33C1SPGSS2_UC3_I2CT_IPSPECIFIC_CTR[EN_DEFDEVADR] Bits */
#define M33C1SPGSS2_UC3_I2CT_IPSPECIFIC_CTR_EN_DEFDEVADR_OFS (9)                             /* !< EN_DEFDEVADR Offset */
#define M33C1SPGSS2_UC3_I2CT_IPSPECIFIC_CTR_EN_DEFDEVADR_MASK ((uint32_t)0x00000200U)         /* !< Enable Default device address */
#define M33C1SPGSS2_UC3_I2CT_IPSPECIFIC_CTR_EN_DEFDEVADR_DISABLE ((uint32_t)0x00000000U)         /* !< When this bit is 0, the default
                                                                                    device address is not matched. NOTE:
                                                                                    it may still be matched if programmed
                                                                                    inside SOAR/SOAR2. */
#define M33C1SPGSS2_UC3_I2CT_IPSPECIFIC_CTR_EN_DEFDEVADR_ENABLE ((uint32_t)0x00000200U)         /* !< When this bit is 1, default device
                                                                                    address of 7h110_0001 is always
                                                                                    matched by the Target address match
                                                                                    logic. */
/* M33C1SPGSS2_UC3_I2CT_IPSPECIFIC_CTR[WUEN] Bits */
#define M33C1SPGSS2_UC3_I2CT_IPSPECIFIC_CTR_WUEN_OFS (21)                            /* !< WUEN Offset */
#define M33C1SPGSS2_UC3_I2CT_IPSPECIFIC_CTR_WUEN_MASK ((uint32_t)0x00200000U)         /* !< Target Wakeup Enable */
#define M33C1SPGSS2_UC3_I2CT_IPSPECIFIC_CTR_WUEN_DISABLE ((uint32_t)0x00000000U)         /* !< When 0, the Target is not allowed
                                                                                    to clock stretch on START detection */
#define M33C1SPGSS2_UC3_I2CT_IPSPECIFIC_CTR_WUEN_ENABLE ((uint32_t)0x00200000U)         /* !< When 1, the Target is allowed to
                                                                                    clock stretch on START detection and
                                                                                    wait for faster clock to be
                                                                                    abvailable. This allows clean wake up
                                                                                    support for I2C in low power mode use
                                                                                    cases */
/* M33C1SPGSS2_UC3_I2CT_IPSPECIFIC_CTR[SUSPEND] Bits */
#define M33C1SPGSS2_UC3_I2CT_IPSPECIFIC_CTR_SUSPEND_OFS (11)                            /* !< SUSPEND Offset */
#define M33C1SPGSS2_UC3_I2CT_IPSPECIFIC_CTR_SUSPEND_MASK ((uint32_t)0x00000800U)         /* !< Suspend external communication */
#define M33C1SPGSS2_UC3_I2CT_IPSPECIFIC_CTR_SUSPEND_DISABLE ((uint32_t)0x00000000U)         /* !< Functional mode resumed */
#define M33C1SPGSS2_UC3_I2CT_IPSPECIFIC_CTR_SUSPEND_ENABLE ((uint32_t)0x00000800U)         /* !< External communication suspended */

/* M33C1SPGSS2_UC3_I2CT_IPSPECIFIC_ACKCTL Bits */
/* M33C1SPGSS2_UC3_I2CT_IPSPECIFIC_ACKCTL[ACKOEN] Bits */
#define M33C1SPGSS2_UC3_I2CT_IPSPECIFIC_ACKCTL_ACKOEN_OFS (0)                             /* !< ACKOEN Offset */
#define M33C1SPGSS2_UC3_I2CT_IPSPECIFIC_ACKCTL_ACKOEN_MASK ((uint32_t)0x00000001U)         /* !< I2C Target ACK Override Enable
                                                                                    Read SR.ACKOEN to check current
                                                                                    status of this bit */
#define M33C1SPGSS2_UC3_I2CT_IPSPECIFIC_ACKCTL_ACKOEN_DISABLE ((uint32_t)0x00000000U)         /* !< A response in not provided. */
#define M33C1SPGSS2_UC3_I2CT_IPSPECIFIC_ACKCTL_ACKOEN_ENABLE ((uint32_t)0x00000001U)         /* !< An ACK or NACK is sent according to
                                                                                    the value written to the ACKOVAL bit. */
/* M33C1SPGSS2_UC3_I2CT_IPSPECIFIC_ACKCTL[ACKOVAL] Bits */
#define M33C1SPGSS2_UC3_I2CT_IPSPECIFIC_ACKCTL_ACKOVAL_OFS (1)                             /* !< ACKOVAL Offset */
#define M33C1SPGSS2_UC3_I2CT_IPSPECIFIC_ACKCTL_ACKOVAL_MASK ((uint32_t)0x00000002U)         /* !< ACK Override Value Note: Override
                                                                                    control is not applicable to Address
                                                                                    frame. Bytes following address frame
                                                                                    can be acknowledged using ACKOVAL. */
#define M33C1SPGSS2_UC3_I2CT_IPSPECIFIC_ACKCTL_ACKOVAL_DISABLE ((uint32_t)0x00000000U)         /* !< An ACK is sent indicating valid
                                                                                    data or command. */
#define M33C1SPGSS2_UC3_I2CT_IPSPECIFIC_ACKCTL_ACKOVAL_ENABLE ((uint32_t)0x00000002U)         /* !< A NACK is sent indicating invalid
                                                                                    data or command. */
/* M33C1SPGSS2_UC3_I2CT_IPSPECIFIC_ACKCTL[ACKOEN_ON_START] Bits */
#define M33C1SPGSS2_UC3_I2CT_IPSPECIFIC_ACKCTL_ACKOEN_ON_START_OFS (2)                             /* !< ACKOEN_ON_START Offset */
#define M33C1SPGSS2_UC3_I2CT_IPSPECIFIC_ACKCTL_ACKOEN_ON_START_MASK ((uint32_t)0x00000004U)         /* !< When set this bit will
                                                                                    automatically enable target override
                                                                                    acknowlede following a Start
                                                                                    Condition. Status bit ACKOEN will
                                                                                    reflect a value of '1' when automatic
                                                                                    override enable is used. */
#define M33C1SPGSS2_UC3_I2CT_IPSPECIFIC_ACKCTL_ACKOEN_ON_START_DISABLE ((uint32_t)0x00000000U)         /* !< No special behavior */
#define M33C1SPGSS2_UC3_I2CT_IPSPECIFIC_ACKCTL_ACKOEN_ON_START_ENABLE ((uint32_t)0x00000004U)         /* !< When set this bit will
                                                                                    automatically turn on the Target
                                                                                    ACKOEN field following a Start
                                                                                    Condition. */
/* M33C1SPGSS2_UC3_I2CT_IPSPECIFIC_ACKCTL[ACKOEN_ON_PECNEXT] Bits */
#define M33C1SPGSS2_UC3_I2CT_IPSPECIFIC_ACKCTL_ACKOEN_ON_PECNEXT_OFS (3)                             /* !< ACKOEN_ON_PECNEXT Offset */
#define M33C1SPGSS2_UC3_I2CT_IPSPECIFIC_ACKCTL_ACKOEN_ON_PECNEXT_MASK ((uint32_t)0x00000008U)         /* !< When set this bit will
                                                                                    automatically turn on the Target
                                                                                    acknowledge override following a
                                                                                    ACK/NACK of the byte received just
                                                                                    prior to the PEC byte. However,
                                                                                    setting ACKCTL.ACKOEN bit will not
                                                                                    automatically be ACKed/NACKed by the
                                                                                    State Machine and firmware must
                                                                                    perform this function by writing
                                                                                    Target.ACKCTL register. Status bit
                                                                                    ACKOEN will reflect a value of '1'
                                                                                    when automatic override enable is
                                                                                    used. */
#define M33C1SPGSS2_UC3_I2CT_IPSPECIFIC_ACKCTL_ACKOEN_ON_PECNEXT_DISABLE ((uint32_t)0x00000000U)         /* !< No special behavior */
#define M33C1SPGSS2_UC3_I2CT_IPSPECIFIC_ACKCTL_ACKOEN_ON_PECNEXT_ENABLE ((uint32_t)0x00000008U)         /* !< When set this bit will
                                                                                    automatically turn on the Target
                                                                                    ACKOEN field following the ACK/NACK
                                                                                    of the byte received just prior to
                                                                                    the PEC byte. Note that when ACKOEN
                                                                                    is set the PEC byte will not
                                                                                    automatically be ACKed/NACKed by the
                                                                                    State Machine and FW must perform
                                                                                    this function by writing
                                                                                    Target_SACKCTL. */
/* M33C1SPGSS2_UC3_I2CT_IPSPECIFIC_ACKCTL[ACKOEN_ON_PECDONE] Bits */
#define M33C1SPGSS2_UC3_I2CT_IPSPECIFIC_ACKCTL_ACKOEN_ON_PECDONE_OFS (4)                             /* !< ACKOEN_ON_PECDONE Offset */
#define M33C1SPGSS2_UC3_I2CT_IPSPECIFIC_ACKCTL_ACKOEN_ON_PECDONE_MASK ((uint32_t)0x00000010U)         /* !< When set, this bit will
                                                                                    automatically turn on target
                                                                                    acknowledge enable field following
                                                                                    the ACK/NACK of the received PEC
                                                                                    byte. Status bit ACKOEN will reflect
                                                                                    a value of '1' when automatic
                                                                                    override enable is used. */
#define M33C1SPGSS2_UC3_I2CT_IPSPECIFIC_ACKCTL_ACKOEN_ON_PECDONE_DISABLE ((uint32_t)0x00000000U)         /* !< No special behavior */
#define M33C1SPGSS2_UC3_I2CT_IPSPECIFIC_ACKCTL_ACKOEN_ON_PECDONE_ENABLE ((uint32_t)0x00000010U)         /* !< When set this bit will
                                                                                    automatically turn on the Target
                                                                                    ACKOEN field following the ACK/NACK
                                                                                    of the received PEC byte. */

/* M33C1SPGSS2_UC3_I2CT_IPSPECIFIC_SR Bits */
/* M33C1SPGSS2_UC3_I2CT_IPSPECIFIC_SR[RREQ] Bits */
#define M33C1SPGSS2_UC3_I2CT_IPSPECIFIC_SR_RREQ_OFS (0)                             /* !< RREQ Offset */
#define M33C1SPGSS2_UC3_I2CT_IPSPECIFIC_SR_RREQ_MASK ((uint32_t)0x00000001U)         /* !< Receive Request */
#define M33C1SPGSS2_UC3_I2CT_IPSPECIFIC_SR_RREQ_CLEARED ((uint32_t)0x00000000U)         /* !< No outstanding receive data. */
#define M33C1SPGSS2_UC3_I2CT_IPSPECIFIC_SR_RREQ_SET ((uint32_t)0x00000001U)         /* !< Module has outstanding receive data
                                                                                    and is using clock stretching to
                                                                                    delay the Controller until the data
                                                                                    has been read from the RXDATA FIFO
                                                                                    (RX FIFO is full). */
/* M33C1SPGSS2_UC3_I2CT_IPSPECIFIC_SR[TREQ] Bits */
#define M33C1SPGSS2_UC3_I2CT_IPSPECIFIC_SR_TREQ_OFS (1)                             /* !< TREQ Offset */
#define M33C1SPGSS2_UC3_I2CT_IPSPECIFIC_SR_TREQ_MASK ((uint32_t)0x00000002U)         /* !< Transmit Request */
#define M33C1SPGSS2_UC3_I2CT_IPSPECIFIC_SR_TREQ_CLEARED ((uint32_t)0x00000000U)         /* !< No outstanding transmit request. */
#define M33C1SPGSS2_UC3_I2CT_IPSPECIFIC_SR_TREQ_SET ((uint32_t)0x00000002U)         /* !< I2C Target is addressed as a
                                                                                    transmitter and is using clock
                                                                                    stretching to delay the Controller
                                                                                    until data has been written to the
                                                                                    TXDATA FIFO (TX FIFO is empty). */
/* M33C1SPGSS2_UC3_I2CT_IPSPECIFIC_SR[OAR2SEL] Bits */
#define M33C1SPGSS2_UC3_I2CT_IPSPECIFIC_SR_OAR2SEL_OFS (3)                             /* !< OAR2SEL Offset */
#define M33C1SPGSS2_UC3_I2CT_IPSPECIFIC_SR_OAR2SEL_MASK ((uint32_t)0x00000008U)         /* !< OAR2 Address Matched This bit gets
                                                                                    reevaluated after every address
                                                                                    comparison. */
#define M33C1SPGSS2_UC3_I2CT_IPSPECIFIC_SR_OAR2SEL_CLEARED ((uint32_t)0x00000000U)         /* !< Either the OAR2 address is not
                                                                                    matched or the match is in legacy
                                                                                    mode. */
#define M33C1SPGSS2_UC3_I2CT_IPSPECIFIC_SR_OAR2SEL_SET ((uint32_t)0x00000008U)         /* !< OAR2 address matched and ACKed by
                                                                                    the Target. */
/* M33C1SPGSS2_UC3_I2CT_IPSPECIFIC_SR[QCMDST] Bits */
#define M33C1SPGSS2_UC3_I2CT_IPSPECIFIC_SR_QCMDST_OFS (4)                             /* !< QCMDST Offset */
#define M33C1SPGSS2_UC3_I2CT_IPSPECIFIC_SR_QCMDST_MASK ((uint32_t)0x00000010U)         /* !< Quick Command Status Value
                                                                                    Description: 0: The last transaction
                                                                                    was a normal transaction or a
                                                                                    transaction has not occurred. 1: The
                                                                                    last transaction was a Quick Command
                                                                                    transaction */
#define M33C1SPGSS2_UC3_I2CT_IPSPECIFIC_SR_QCMDST_CLEARED ((uint32_t)0x00000000U)         /* !< The last transaction was a normal
                                                                                    transaction or a transaction has not
                                                                                    occurred. */
#define M33C1SPGSS2_UC3_I2CT_IPSPECIFIC_SR_QCMDST_SET ((uint32_t)0x00000010U)         /* !< The last transaction was a Quick
                                                                                    Command transaction. */
/* M33C1SPGSS2_UC3_I2CT_IPSPECIFIC_SR[QCMDRW] Bits */
#define M33C1SPGSS2_UC3_I2CT_IPSPECIFIC_SR_QCMDRW_OFS (5)                             /* !< QCMDRW Offset */
#define M33C1SPGSS2_UC3_I2CT_IPSPECIFIC_SR_QCMDRW_MASK ((uint32_t)0x00000020U)         /* !< Quick Command Read / Write  This
                                                                                    bit only has meaning when the QCMDST
                                                                                    bit is set.  Value Description: 0:
                                                                                    Quick command was a write 1: Quick
                                                                                    command was a read */
#define M33C1SPGSS2_UC3_I2CT_IPSPECIFIC_SR_QCMDRW_CLEARED ((uint32_t)0x00000000U)         /* !< Quick command was a write */
#define M33C1SPGSS2_UC3_I2CT_IPSPECIFIC_SR_QCMDRW_SET ((uint32_t)0x00000020U)         /* !< Quick command was a read */
/* M33C1SPGSS2_UC3_I2CT_IPSPECIFIC_SR[RXMODE] Bits */
#define M33C1SPGSS2_UC3_I2CT_IPSPECIFIC_SR_RXMODE_OFS (2)                             /* !< RXMODE Offset */
#define M33C1SPGSS2_UC3_I2CT_IPSPECIFIC_SR_RXMODE_MASK ((uint32_t)0x00000004U)         /* !< Target FSM is in Rx MODE */
#define M33C1SPGSS2_UC3_I2CT_IPSPECIFIC_SR_RXMODE_CLEARED ((uint32_t)0x00000000U)         /* !< The Target State Machine is not in
                                                                                    the RX_DATA, RX_ACK, RX_WAIT,
                                                                                    RX_ACK_WAIT or ADDR_ACK state with
                                                                                    the bus direction set to write. */
#define M33C1SPGSS2_UC3_I2CT_IPSPECIFIC_SR_RXMODE_SET ((uint32_t)0x00000004U)         /* !< The Target State Machine is in the
                                                                                    RX_DATA, RX_ACK, RX_WAIT, RX_ACK_WAIT
                                                                                    or ADDR_ACK state with the bus
                                                                                    direction set to write. */
/* M33C1SPGSS2_UC3_I2CT_IPSPECIFIC_SR[BUSBSY] Bits */
#define M33C1SPGSS2_UC3_I2CT_IPSPECIFIC_SR_BUSBSY_OFS (6)                             /* !< BUSBSY Offset */
#define M33C1SPGSS2_UC3_I2CT_IPSPECIFIC_SR_BUSBSY_MASK ((uint32_t)0x00000040U)         /* !< I2C bus is busy */
#define M33C1SPGSS2_UC3_I2CT_IPSPECIFIC_SR_BUSBSY_CLEARED ((uint32_t)0x00000000U)         /* !< The I2C Bus is not busy */
#define M33C1SPGSS2_UC3_I2CT_IPSPECIFIC_SR_BUSBSY_SET ((uint32_t)0x00000040U)         /* !< The I2C Bus is busy. This is
                                                                                    cleared on a timeout. */
/* M33C1SPGSS2_UC3_I2CT_IPSPECIFIC_SR[TXMODE] Bits */
#define M33C1SPGSS2_UC3_I2CT_IPSPECIFIC_SR_TXMODE_OFS (7)                             /* !< TXMODE Offset */
#define M33C1SPGSS2_UC3_I2CT_IPSPECIFIC_SR_TXMODE_MASK ((uint32_t)0x00000080U)         /* !< FSM is in TX MODE */
#define M33C1SPGSS2_UC3_I2CT_IPSPECIFIC_SR_TXMODE_CLEARED ((uint32_t)0x00000000U)         /* !< State Machine is not in TX_DATA,
                                                                                    TX_WAIT, TX_ACK  or ADDR_ACK state
                                                                                    with the bus direction set to read. */
#define M33C1SPGSS2_UC3_I2CT_IPSPECIFIC_SR_TXMODE_SET ((uint32_t)0x00000080U)         /* !< State Machine is in TX_DATA,
                                                                                    TX_WAIT, TX_ACK  or ADDR_ACK state
                                                                                    with the bus direction set to read. */
/* M33C1SPGSS2_UC3_I2CT_IPSPECIFIC_SR[STALE_TXFIFO] Bits */
#define M33C1SPGSS2_UC3_I2CT_IPSPECIFIC_SR_STALE_TXFIFO_OFS (8)                             /* !< STALE_TXFIFO Offset */
#define M33C1SPGSS2_UC3_I2CT_IPSPECIFIC_SR_STALE_TXFIFO_MASK ((uint32_t)0x00000100U)         /* !< Stale Tx FIFO */
#define M33C1SPGSS2_UC3_I2CT_IPSPECIFIC_SR_STALE_TXFIFO_CLEARED ((uint32_t)0x00000000U)         /* !< Tx FIFO is not stale */
#define M33C1SPGSS2_UC3_I2CT_IPSPECIFIC_SR_STALE_TXFIFO_SET ((uint32_t)0x00000100U)         /* !< The TX FIFO is stale. This occurs
                                                                                    when the TX FIFO was not emptied
                                                                                    during the previous I2C transaction. */
/* M33C1SPGSS2_UC3_I2CT_IPSPECIFIC_SR[ADDRMATCH] Bits */
#define M33C1SPGSS2_UC3_I2CT_IPSPECIFIC_SR_ADDRMATCH_OFS (16)                            /* !< ADDRMATCH Offset */
#define M33C1SPGSS2_UC3_I2CT_IPSPECIFIC_SR_ADDRMATCH_MASK ((uint32_t)0x03FF0000U)         /* !< Indicates the address for which
                                                                                    Target address match happened */
#define M33C1SPGSS2_UC3_I2CT_IPSPECIFIC_SR_ADDRMATCH_MINIMUM ((uint32_t)0x00000000U)         /* !< Minimum Value */
#define M33C1SPGSS2_UC3_I2CT_IPSPECIFIC_SR_ADDRMATCH_MAXIMUM ((uint32_t)0x03FF0000U)         /* !< Maximum Value */
/* M33C1SPGSS2_UC3_I2CT_IPSPECIFIC_SR[RXCLR] Bits */
#define M33C1SPGSS2_UC3_I2CT_IPSPECIFIC_SR_RXCLR_OFS (9)                             /* !< RXCLR Offset */
#define M33C1SPGSS2_UC3_I2CT_IPSPECIFIC_SR_RXCLR_MASK ((uint32_t)0x00000200U)         /* !< RX FIFO Clear Status */
#define M33C1SPGSS2_UC3_I2CT_IPSPECIFIC_SR_RXCLR_CLEARED ((uint32_t)0x00000000U)         /* !< FIFO is not cleared */
#define M33C1SPGSS2_UC3_I2CT_IPSPECIFIC_SR_RXCLR_SET ((uint32_t)0x00000200U)         /* !< FIFO clear is complete */
/* M33C1SPGSS2_UC3_I2CT_IPSPECIFIC_SR[TXCLR] Bits */
#define M33C1SPGSS2_UC3_I2CT_IPSPECIFIC_SR_TXCLR_OFS (10)                            /* !< TXCLR Offset */
#define M33C1SPGSS2_UC3_I2CT_IPSPECIFIC_SR_TXCLR_MASK ((uint32_t)0x00000400U)         /* !< TX FIFO Clear Status */
#define M33C1SPGSS2_UC3_I2CT_IPSPECIFIC_SR_TXCLR_CLEARED ((uint32_t)0x00000000U)         /* !< FIFO is not cleared */
#define M33C1SPGSS2_UC3_I2CT_IPSPECIFIC_SR_TXCLR_SET ((uint32_t)0x00000400U)         /* !< FIFO clear is complete */
/* M33C1SPGSS2_UC3_I2CT_IPSPECIFIC_SR[RXFE] Bits */
#define M33C1SPGSS2_UC3_I2CT_IPSPECIFIC_SR_RXFE_OFS (11)                            /* !< RXFE Offset */
#define M33C1SPGSS2_UC3_I2CT_IPSPECIFIC_SR_RXFE_MASK ((uint32_t)0x00000800U)         /* !< Receive FIFO Empty  The meaning of
                                                                                    this bit depends on the state of the
                                                                                    FEN bit in the CTL0 register. */
#define M33C1SPGSS2_UC3_I2CT_IPSPECIFIC_SR_RXFE_CLEARED ((uint32_t)0x00000000U)         /* !< The receiver is not empty. */
#define M33C1SPGSS2_UC3_I2CT_IPSPECIFIC_SR_RXFE_SET ((uint32_t)0x00000800U)         /* !< If the FIFO is disabled (FEN is 0),
                                                                                    the receive holding register is
                                                                                    empty. If the FIFO is enabled (FEN is
                                                                                    1), the receive FIFO is empty. */
/* M33C1SPGSS2_UC3_I2CT_IPSPECIFIC_SR[RXFF] Bits */
#define M33C1SPGSS2_UC3_I2CT_IPSPECIFIC_SR_RXFF_OFS (12)                            /* !< RXFF Offset */
#define M33C1SPGSS2_UC3_I2CT_IPSPECIFIC_SR_RXFF_MASK ((uint32_t)0x00001000U)         /* !< Receive FIFO Full  The meaning of
                                                                                    this bit depends on the state of the
                                                                                    FEN bit in the CTL0 register. */
#define M33C1SPGSS2_UC3_I2CT_IPSPECIFIC_SR_RXFF_CLEARED ((uint32_t)0x00000000U)         /* !< The receiver can receive data. */
#define M33C1SPGSS2_UC3_I2CT_IPSPECIFIC_SR_RXFF_SET ((uint32_t)0x00001000U)         /* !< If the FIFO is disabled (FEN is 0),
                                                                                    the receive holding register is full.
                                                                                    If the FIFO is enabled (FEN is 1),
                                                                                    the receive FIFO is full. */
/* M33C1SPGSS2_UC3_I2CT_IPSPECIFIC_SR[TXFE] Bits */
#define M33C1SPGSS2_UC3_I2CT_IPSPECIFIC_SR_TXFE_OFS (13)                            /* !< TXFE Offset */
#define M33C1SPGSS2_UC3_I2CT_IPSPECIFIC_SR_TXFE_MASK ((uint32_t)0x00002000U)         /* !< Transmit FIFO Empty  The meaning of
                                                                                    this bit depends on the state of the
                                                                                    FEN bit in the CTL0 register. */
#define M33C1SPGSS2_UC3_I2CT_IPSPECIFIC_SR_TXFE_CLEARED ((uint32_t)0x00000000U)         /* !< The transmitter has data to
                                                                                    transmit. */
#define M33C1SPGSS2_UC3_I2CT_IPSPECIFIC_SR_TXFE_SET ((uint32_t)0x00002000U)         /* !< If the FIFO is disabled (FEN is 0),
                                                                                    the transmit holding register is
                                                                                    empty. If the FIFO is enabled (FEN is
                                                                                    1), the transmit FIFO is empty. */
/* M33C1SPGSS2_UC3_I2CT_IPSPECIFIC_SR[TXFF] Bits */
#define M33C1SPGSS2_UC3_I2CT_IPSPECIFIC_SR_TXFF_OFS (14)                            /* !< TXFF Offset */
#define M33C1SPGSS2_UC3_I2CT_IPSPECIFIC_SR_TXFF_MASK ((uint32_t)0x00004000U)         /* !< Transmit FIFO Full  The meaning of
                                                                                    this bit depends on the state of the
                                                                                    FEN bit in the CTL0 register. */
#define M33C1SPGSS2_UC3_I2CT_IPSPECIFIC_SR_TXFF_CLEARED ((uint32_t)0x00000000U)         /* !< The transmitter is not full. */
#define M33C1SPGSS2_UC3_I2CT_IPSPECIFIC_SR_TXFF_SET ((uint32_t)0x00004000U)         /* !< If the FIFO is disabled (FEN is 0),
                                                                                    the transmit holding register is
                                                                                    full. If the FIFO is enabled (FEN is
                                                                                    1), the transmit FIFO is full. */
/* M33C1SPGSS2_UC3_I2CT_IPSPECIFIC_SR[ACKOEN] Bits */
#define M33C1SPGSS2_UC3_I2CT_IPSPECIFIC_SR_ACKOEN_OFS (15)                            /* !< ACKOEN Offset */
#define M33C1SPGSS2_UC3_I2CT_IPSPECIFIC_SR_ACKOEN_MASK ((uint32_t)0x00008000U)         /* !< Status of ACK Override Enable */
#define M33C1SPGSS2_UC3_I2CT_IPSPECIFIC_SR_ACKOEN_DISABLE ((uint32_t)0x00000000U)         /* !< ACK override is disabled */
#define M33C1SPGSS2_UC3_I2CT_IPSPECIFIC_SR_ACKOEN_ENABLE ((uint32_t)0x00008000U)         /* !< ACK override was enabled in design */

/* M33C1SPGSS2_UC3_I2CT_IPSPECIFIC_IFLS Bits */
/* M33C1SPGSS2_UC3_I2CT_IPSPECIFIC_IFLS[TXIFLSEL] Bits */
#define M33C1SPGSS2_UC3_I2CT_IPSPECIFIC_IFLS_TXIFLSEL_OFS (0)                             /* !< TXIFLSEL Offset */
#define M33C1SPGSS2_UC3_I2CT_IPSPECIFIC_IFLS_TXIFLSEL_MASK ((uint32_t)0x00000007U)         /* !< FIFO Level Select for generating
                                                                                    events (interrupt/dma).  Note: for
                                                                                    undefined settings the default
                                                                                    configuration is used. */
#define M33C1SPGSS2_UC3_I2CT_IPSPECIFIC_IFLS_TXIFLSEL_LVL_3_4 ((uint32_t)0x00000001U)         /* !< TX FIFO <= 3/4 empty */
#define M33C1SPGSS2_UC3_I2CT_IPSPECIFIC_IFLS_TXIFLSEL_LVL_1_2 ((uint32_t)0x00000002U)         /* !< TX FIFO <= 1/2 empty (default) */
#define M33C1SPGSS2_UC3_I2CT_IPSPECIFIC_IFLS_TXIFLSEL_LVL_1_4 ((uint32_t)0x00000003U)         /* !< TX FIFO <= 1/4 empty */
#define M33C1SPGSS2_UC3_I2CT_IPSPECIFIC_IFLS_TXIFLSEL_LVL_NOT_FULL ((uint32_t)0x00000004U)         /* !< Opposite of full */
#define M33C1SPGSS2_UC3_I2CT_IPSPECIFIC_IFLS_TXIFLSEL_LVL_EMPTY ((uint32_t)0x00000005U)         /* !< TX FIFO is empty */
#define M33C1SPGSS2_UC3_I2CT_IPSPECIFIC_IFLS_TXIFLSEL_LVL_ALMOST_EMPTY ((uint32_t)0x00000006U)         /* !< TX FIFO <= 1 */
#define M33C1SPGSS2_UC3_I2CT_IPSPECIFIC_IFLS_TXIFLSEL_LVL_ALMOST_FULL ((uint32_t)0x00000007U)         /* !< TX_FIFO >= (MAX_FIFO_LEN -1) */
/* M33C1SPGSS2_UC3_I2CT_IPSPECIFIC_IFLS[RXIFLSEL] Bits */
#define M33C1SPGSS2_UC3_I2CT_IPSPECIFIC_IFLS_RXIFLSEL_OFS (4)                             /* !< RXIFLSEL Offset */
#define M33C1SPGSS2_UC3_I2CT_IPSPECIFIC_IFLS_RXIFLSEL_MASK ((uint32_t)0x00000070U)         /* !< FIFO Level Select for generating
                                                                                    events (interrupt/dma).  Note: for
                                                                                    undefined settings the default
                                                                                    configuration is used. */
#define M33C1SPGSS2_UC3_I2CT_IPSPECIFIC_IFLS_RXIFLSEL_LVL_1_4 ((uint32_t)0x00000010U)         /* !< RX FIFO >= 1/4 full */
