#define M33C1SPGSS2_UC2_I2CT_IPSPECIFIC_OAR_OAREN_OFS (14)                            /* !< OAREN Offset */
#define M33C1SPGSS2_UC2_I2CT_IPSPECIFIC_OAR_OAREN_MASK ((uint32_t)0x00004000U)         /* !< Own Address Enable */
#define M33C1SPGSS2_UC2_I2CT_IPSPECIFIC_OAR_OAREN_DISABLE ((uint32_t)0x00000000U)         /* !< Disable OAR address */
#define M33C1SPGSS2_UC2_I2CT_IPSPECIFIC_OAR_OAREN_ENABLE ((uint32_t)0x00004000U)         /* !< Enable OAR address */
