#define M33C1SPGSS2_UC3_I2CC_IPSTANDARD_PDBGCTL_FREE_OFS (0)                             /* !< FREE Offset */
#define M33C1SPGSS2_UC3_I2CC_IPSTANDARD_PDBGCTL_FREE_MASK ((uint32_t)0x00000001U)         /* !< Free run control */
#define M33C1SPGSS2_UC3_I2CC_IPSTANDARD_PDBGCTL_FREE_STOP ((uint32_t)0x00000000U)         /* !< The peripheral freezes
                                                                                    functionality while the Core Halted
                                                                                    input is asserted and resumes when it
                                                                                    is deasserted. */
#define M33C1SPGSS2_UC3_I2CC_IPSTANDARD_PDBGCTL_FREE_RUN ((uint32_t)0x00000001U)         /* !< The peripheral ignores the state of
                                                                                    the Core Halted input */
/* M33C1SPGSS2_UC3_I2CC_IPSTANDARD_PDBGCTL[SOFT] Bits */
#define M33C1SPGSS2_UC3_I2CC_IPSTANDARD_PDBGCTL_SOFT_OFS (1)                             /* !< SOFT Offset */
#define M33C1SPGSS2_UC3_I2CC_IPSTANDARD_PDBGCTL_SOFT_MASK ((uint32_t)0x00000002U)         /* !< Soft halt boundary control. This
                                                                                    function is only available, if [FREE]
                                                                                    is set to 'STOP' */
#define M33C1SPGSS2_UC3_I2CC_IPSTANDARD_PDBGCTL_SOFT_DEPRECATED ((uint32_t)0x00000000U)         /* !< Not supported */
#define M33C1SPGSS2_UC3_I2CC_IPSTANDARD_PDBGCTL_SOFT_DELAYED ((uint32_t)0x00000002U)         /* !< The peripheral blocks the debug
                                                                                    freeze until it has reached a
                                                                                    boundary where it can resume without
                                                                                    corruption */

/* M33C1SPGSS2_UC3_I2CC_IPSTANDARD_INTCTL Bits */
/* M33C1SPGSS2_UC3_I2CC_IPSTANDARD_INTCTL[INTEVAL] Bits */
#define M33C1SPGSS2_UC3_I2CC_IPSTANDARD_INTCTL_INTEVAL_OFS (0)                             /* !< INTEVAL Offset */
#define M33C1SPGSS2_UC3_I2CC_IPSTANDARD_INTCTL_INTEVAL_MASK ((uint32_t)0x00000001U)         /* !< Writing a 1 to this field
                                                                                    re-evaluates the interrupt sources. */
#define M33C1SPGSS2_UC3_I2CC_IPSTANDARD_INTCTL_INTEVAL_DISABLE ((uint32_t)0x00000000U)         /* !< The interrupt or event line is
                                                                                    disabled. */
#define M33C1SPGSS2_UC3_I2CC_IPSTANDARD_INTCTL_INTEVAL_EVAL ((uint32_t)0x00000001U)         /* !< The interrupt or event line is in
                                                                                    software mode. Software must clear
                                                                                    the RIS. */

/* M33C1SPGSS2_UC2_I2CC_LMGMT_DFT_ATRT_TEST0 Bits */
/* M33C1SPGSS2_UC2_I2CC_LMGMT_DFT_ATRT_TEST0[DTB_MUX_SEL] Bits */
#define M33C1SPGSS2_UC2_I2CC_LMGMT_DFT_ATRT_TEST0_DTB_MUX_SEL_OFS (0)                             /* !< DTB_MUX_SEL Offset */
#define M33C1SPGSS2_UC2_I2CC_LMGMT_DFT_ATRT_TEST0_DTB_MUX_SEL_MASK ((uint32_t)0x0000001FU)         /* !< This bit field is used to select
                                                                                    DTB mux digital output signals. */
#define M33C1SPGSS2_UC2_I2CC_LMGMT_DFT_ATRT_TEST0_DTB_MUX_SEL_DISABLE ((uint32_t)0x00000000U)         /* !< Disables DTB MUX */
#define M33C1SPGSS2_UC2_I2CC_LMGMT_DFT_ATRT_TEST0_DTB_MUX_SEL_GRP1 ((uint32_t)0x00000001U)         /* !< Selects test group 1 */
#define M33C1SPGSS2_UC2_I2CC_LMGMT_DFT_ATRT_TEST0_DTB_MUX_SEL_GRP2 ((uint32_t)0x00000002U)         /* !< Selects test group 2 */
#define M33C1SPGSS2_UC2_I2CC_LMGMT_DFT_ATRT_TEST0_DTB_MUX_SEL_GRP3 ((uint32_t)0x00000003U)         /* !< Selects test group 3 */
#define M33C1SPGSS2_UC2_I2CC_LMGMT_DFT_ATRT_TEST0_DTB_MUX_SEL_GRP4 ((uint32_t)0x00000004U)         /* !< Selects test group 4 */
#define M33C1SPGSS2_UC2_I2CC_LMGMT_DFT_ATRT_TEST0_DTB_MUX_SEL_GRP5 ((uint32_t)0x00000005U)         /* !< Selects test group 5 */
#define M33C1SPGSS2_UC2_I2CC_LMGMT_DFT_ATRT_TEST0_DTB_MUX_SEL_GRP6 ((uint32_t)0x00000006U)         /* !< Selects test group 6 */
#define M33C1SPGSS2_UC2_I2CC_LMGMT_DFT_ATRT_TEST0_DTB_MUX_SEL_GRP7 ((uint32_t)0x00000007U)         /* !< Selects test group 7 */

/* M33C1SPGSS2_UC2_I2CC_IPSPECIFIC_CTR Bits */
/* M33C1SPGSS2_UC2_I2CC_IPSPECIFIC_CTR[FRM_START] Bits */
#define M33C1SPGSS2_UC2_I2CC_IPSPECIFIC_CTR_FRM_START_OFS (0)                             /* !< FRM_START Offset */
#define M33C1SPGSS2_UC2_I2CC_IPSPECIFIC_CTR_FRM_START_MASK ((uint32_t)0x00000001U)         /* !< Start Transfer */
#define M33C1SPGSS2_UC2_I2CC_IPSPECIFIC_CTR_FRM_START_DISABLE ((uint32_t)0x00000000U)         /* !< In standard mode, this encoding
                                                                                    means the Controller is unable to
                                                                                    transmit or receive data. */
#define M33C1SPGSS2_UC2_I2CC_IPSPECIFIC_CTR_FRM_START_ENABLE ((uint32_t)0x00000001U)         /* !< The Controller is able to transmit
                                                                                    or receive data. See field decoding
                                                                                    in Table: MCTR Field decoding. */
/* M33C1SPGSS2_UC2_I2CC_IPSPECIFIC_CTR[START] Bits */
#define M33C1SPGSS2_UC2_I2CC_IPSPECIFIC_CTR_START_OFS (1)                             /* !< START Offset */
#define M33C1SPGSS2_UC2_I2CC_IPSPECIFIC_CTR_START_MASK ((uint32_t)0x00000002U)         /* !< Generate START */
#define M33C1SPGSS2_UC2_I2CC_IPSPECIFIC_CTR_START_DISABLE ((uint32_t)0x00000000U)         /* !< The controller does not generate
                                                                                    the START condition. */
#define M33C1SPGSS2_UC2_I2CC_IPSPECIFIC_CTR_START_ENABLE ((uint32_t)0x00000002U)         /* !< The controller generates the START
                                                                                    or repeated START condition. See
                                                                                    field decoding in Table: MCTR Field
                                                                                    decoding. */
/* M33C1SPGSS2_UC2_I2CC_IPSPECIFIC_CTR[STOP] Bits */
#define M33C1SPGSS2_UC2_I2CC_IPSPECIFIC_CTR_STOP_OFS (2)                             /* !< STOP Offset */
#define M33C1SPGSS2_UC2_I2CC_IPSPECIFIC_CTR_STOP_MASK ((uint32_t)0x00000004U)         /* !< Generate STOP */
#define M33C1SPGSS2_UC2_I2CC_IPSPECIFIC_CTR_STOP_DISABLE ((uint32_t)0x00000000U)         /* !< The controller does not generate
                                                                                    the STOP condition. */
#define M33C1SPGSS2_UC2_I2CC_IPSPECIFIC_CTR_STOP_ENABLE ((uint32_t)0x00000004U)         /* !< The controller generates the STOP
                                                                                    condition. See field decoding in
                                                                                    Table: MCTR Field decoding. */
/* M33C1SPGSS2_UC2_I2CC_IPSPECIFIC_CTR[ACK] Bits */
#define M33C1SPGSS2_UC2_I2CC_IPSPECIFIC_CTR_ACK_OFS (3)                             /* !< ACK Offset */
#define M33C1SPGSS2_UC2_I2CC_IPSPECIFIC_CTR_ACK_MASK ((uint32_t)0x00000008U)         /* !< Data Acknowledge Enable. Software
                                                                                    needs to configure this bit to send
                                                                                    the ACK or NACK. See field decoding
                                                                                    in Table: MCTR Field decoding. */
#define M33C1SPGSS2_UC2_I2CC_IPSPECIFIC_CTR_ACK_DISABLE ((uint32_t)0x00000000U)         /* !< The last received data byte of a
                                                                                    transaction is not acknowledged
                                                                                    automatically . */
#define M33C1SPGSS2_UC2_I2CC_IPSPECIFIC_CTR_ACK_ENABLE ((uint32_t)0x00000008U)         /* !< The last received data byte of a
                                                                                    transaction is acknowledged
                                                                                    automatically . */
/* M33C1SPGSS2_UC2_I2CC_IPSPECIFIC_CTR[ACKOEN] Bits */
#define M33C1SPGSS2_UC2_I2CC_IPSPECIFIC_CTR_ACKOEN_OFS (4)                             /* !< ACKOEN Offset */
#define M33C1SPGSS2_UC2_I2CC_IPSPECIFIC_CTR_ACKOEN_MASK ((uint32_t)0x00000010U)         /* !< ACK overrride Enable */
#define M33C1SPGSS2_UC2_I2CC_IPSPECIFIC_CTR_ACKOEN_DISABLE ((uint32_t)0x00000000U)         /* !< No special behavior */
#define M33C1SPGSS2_UC2_I2CC_IPSPECIFIC_CTR_ACKOEN_ENABLE ((uint32_t)0x00000010U)         /* !< When 1 and the Controller is
                                                                                    receiving data and the number of
                                                                                    bytes indicated in MBLEN have been
                                                                                    received, the state machine will
                                                                                    generate an rxdone interrupt and wait
                                                                                    at the start of the ACK for FW to
                                                                                    indicate if an ACK or NACK should be
                                                                                    sent. The ACK or NACK is selected by
                                                                                    writing the MCTR register and setting
                                                                                    ACK accordingly. The other fields in
                                                                                    this register can also be written at
                                                                                    this time to continue on with the
                                                                                    transaction. If a NACK is sent the
                                                                                    state machine will automatically send
                                                                                    a Stop. */
/* M33C1SPGSS2_UC2_I2CC_IPSPECIFIC_CTR[RD_ON_TXEMPTY] Bits */
#define M33C1SPGSS2_UC2_I2CC_IPSPECIFIC_CTR_RD_ON_TXEMPTY_OFS (5)                             /* !< RD_ON_TXEMPTY Offset */
#define M33C1SPGSS2_UC2_I2CC_IPSPECIFIC_CTR_RD_ON_TXEMPTY_MASK ((uint32_t)0x00000020U)         /* !< Read on TX Empty */
#define M33C1SPGSS2_UC2_I2CC_IPSPECIFIC_CTR_RD_ON_TXEMPTY_DISABLE ((uint32_t)0x00000000U)         /* !< No special behavior */
#define M33C1SPGSS2_UC2_I2CC_IPSPECIFIC_CTR_RD_ON_TXEMPTY_ENABLE ((uint32_t)0x00000020U)         /* !< When 1 the Controller will transmit
                                                                                    all bytes from the TX FIFO before
                                                                                    continuing with the programmed Burst
                                                                                    Run Read. If the DIR is not set to
                                                                                    Read in the MSA then this bit is
                                                                                    ignored. The Start must be set in the
                                                                                    MCTR for proper I2C protocol. The
                                                                                    Controller will first send the Start
                                                                                    Condition, I2C Address with R/W bit
                                                                                    set to write, before sending the
                                                                                    bytes in the TX FIFO. When the TX
                                                                                    FIFO is empty, the I2C transaction
                                                                                    will continue as programmed in MTCR
                                                                                    and MSA without sending a Stop
                                                                                    Condition. This is intended to be
                                                                                    used to perform simple I2C command
                                                                                    based reads transition that will
                                                                                    complete after initiating them
                                                                                    without having to get an interrupt to
                                                                                    turn the bus around. */
/* M33C1SPGSS2_UC2_I2CC_IPSPECIFIC_CTR[SUSPEND] Bits */
#define M33C1SPGSS2_UC2_I2CC_IPSPECIFIC_CTR_SUSPEND_OFS (6)                             /* !< SUSPEND Offset */
#define M33C1SPGSS2_UC2_I2CC_IPSPECIFIC_CTR_SUSPEND_MASK ((uint32_t)0x00000040U)         /* !< Suspend external communication */
#define M33C1SPGSS2_UC2_I2CC_IPSPECIFIC_CTR_SUSPEND_DISABLE ((uint32_t)0x00000000U)         /* !< Functional mode resumed */
#define M33C1SPGSS2_UC2_I2CC_IPSPECIFIC_CTR_SUSPEND_ENABLE ((uint32_t)0x00000040U)         /* !< External communication suspended */

/* M33C1SPGSS2_UC2_I2CC_IPSPECIFIC_CR Bits */
/* M33C1SPGSS2_UC2_I2CC_IPSPECIFIC_CR[MCTL] Bits */
#define M33C1SPGSS2_UC2_I2CC_IPSPECIFIC_CR_MCTL_OFS (1)                             /* !< MCTL Offset */
#define M33C1SPGSS2_UC2_I2CC_IPSPECIFIC_CR_MCTL_MASK ((uint32_t)0x00000002U)         /* !< MultiController mode. In
                                                                                    MultiController mode the SCL high
                                                                                    time counts once the SCL line has
                                                                                    been detected high. If this is not
                                                                                    enabled the high time counts as soon
                                                                                    as the SCL line has been set high by
                                                                                    the I2C controller. */
#define M33C1SPGSS2_UC2_I2CC_IPSPECIFIC_CR_MCTL_DISABLE ((uint32_t)0x00000000U)         /* !< Disable MultiController mode. */
#define M33C1SPGSS2_UC2_I2CC_IPSPECIFIC_CR_MCTL_ENABLE ((uint32_t)0x00000002U)         /* !< Enable MultiController mode. */
/* M33C1SPGSS2_UC2_I2CC_IPSPECIFIC_CR[ENABLE] Bits */
#define M33C1SPGSS2_UC2_I2CC_IPSPECIFIC_CR_ENABLE_OFS (0)                             /* !< ENABLE Offset */
#define M33C1SPGSS2_UC2_I2CC_IPSPECIFIC_CR_ENABLE_MASK ((uint32_t)0x00000001U)         /* !< Enable module.  After this bit has
                                                                                    been set, it should not be set again
                                                                                    unless it has been cleared by writing
                                                                                    a 0 or by a reset, otherwise transfer
                                                                                    failures may occur. */
#define M33C1SPGSS2_UC2_I2CC_IPSPECIFIC_CR_ENABLE_DISABLE ((uint32_t)0x00000000U)         /* !< Disables operation. */
#define M33C1SPGSS2_UC2_I2CC_IPSPECIFIC_CR_ENABLE_ENABLE ((uint32_t)0x00000001U)         /* !< Enables operation. */
/* M33C1SPGSS2_UC2_I2CC_IPSPECIFIC_CR[CLKSTRETCH] Bits */
#define M33C1SPGSS2_UC2_I2CC_IPSPECIFIC_CR_CLKSTRETCH_OFS (2)                             /* !< CLKSTRETCH Offset */
#define M33C1SPGSS2_UC2_I2CC_IPSPECIFIC_CR_CLKSTRETCH_MASK ((uint32_t)0x00000004U)         /* !< Clock Stretching. This bit controls
                                                                                    the support for clock stretching of
                                                                                    the I2C bus. */
#define M33C1SPGSS2_UC2_I2CC_IPSPECIFIC_CR_CLKSTRETCH_DISABLE ((uint32_t)0x00000000U)         /* !< Disables the clock stretching
                                                                                    detection. This can be disabled if no
                                                                                    Target on the bus does support clock
                                                                                    stretching, so that the maximum speed
                                                                                    on the bus can be reached. */
#define M33C1SPGSS2_UC2_I2CC_IPSPECIFIC_CR_CLKSTRETCH_ENABLE ((uint32_t)0x00000004U)         /* !< Enables the clock stretching
                                                                                    detection. Enabling the clock
                                                                                    stretching ensures compliance to the
                                                                                    I2C standard but could limit the
                                                                                    speed due the clock stretching. */

/* M33C1SPGSS2_UC2_I2CC_IPSPECIFIC_SR Bits */
/* M33C1SPGSS2_UC2_I2CC_IPSPECIFIC_SR[BUSY] Bits */
#define M33C1SPGSS2_UC2_I2CC_IPSPECIFIC_SR_BUSY_OFS (0)                             /* !< BUSY Offset */
#define M33C1SPGSS2_UC2_I2CC_IPSPECIFIC_SR_BUSY_MASK ((uint32_t)0x00000001U)         /* !< FSM Busy The BUSY bit is set during
                                                                                    an ongoing transaction, so is set
                                                                                    during the transmit/receive of the
                                                                                    amount of data set in MBLEN including
                                                                                    START, RESTART, Address and STOP
                                                                                    signal generation when required for
                                                                                    the current transaction. */
#define M33C1SPGSS2_UC2_I2CC_IPSPECIFIC_SR_BUSY_CLEARED ((uint32_t)0x00000000U)         /* !< The controller is idle. */
#define M33C1SPGSS2_UC2_I2CC_IPSPECIFIC_SR_BUSY_SET ((uint32_t)0x00000001U)         /* !< The controller is busy. */
/* M33C1SPGSS2_UC2_I2CC_IPSPECIFIC_SR[ERR] Bits */
#define M33C1SPGSS2_UC2_I2CC_IPSPECIFIC_SR_ERR_OFS (1)                             /* !< ERR Offset */
#define M33C1SPGSS2_UC2_I2CC_IPSPECIFIC_SR_ERR_MASK ((uint32_t)0x00000002U)         /* !< Error  The error can be from the
                                                                                    Target address not being acknowledged
                                                                                    or the transmit data not being
                                                                                    acknowledged. */
#define M33C1SPGSS2_UC2_I2CC_IPSPECIFIC_SR_ERR_CLEARED ((uint32_t)0x00000000U)         /* !< No error was detected on the last
                                                                                    operation. */
#define M33C1SPGSS2_UC2_I2CC_IPSPECIFIC_SR_ERR_SET ((uint32_t)0x00000002U)         /* !< An error occurred on the last
                                                                                    operation. */
/* M33C1SPGSS2_UC2_I2CC_IPSPECIFIC_SR[ADRACK] Bits */
#define M33C1SPGSS2_UC2_I2CC_IPSPECIFIC_SR_ADRACK_OFS (2)                             /* !< ADRACK Offset */
#define M33C1SPGSS2_UC2_I2CC_IPSPECIFIC_SR_ADRACK_MASK ((uint32_t)0x00000004U)         /* !< Acknowledge Address */
#define M33C1SPGSS2_UC2_I2CC_IPSPECIFIC_SR_ADRACK_CLEARED ((uint32_t)0x00000000U)         /* !< The transmitted address was
                                                                                    acknowledged */
#define M33C1SPGSS2_UC2_I2CC_IPSPECIFIC_SR_ADRACK_SET ((uint32_t)0x00000004U)         /* !< The transmitted address was not
                                                                                    acknowledged. */
/* M33C1SPGSS2_UC2_I2CC_IPSPECIFIC_SR[DATACK] Bits */
#define M33C1SPGSS2_UC2_I2CC_IPSPECIFIC_SR_DATACK_OFS (3)                             /* !< DATACK Offset */
#define M33C1SPGSS2_UC2_I2CC_IPSPECIFIC_SR_DATACK_MASK ((uint32_t)0x00000008U)         /* !< Acknowledge Data */
#define M33C1SPGSS2_UC2_I2CC_IPSPECIFIC_SR_DATACK_CLEARED ((uint32_t)0x00000000U)         /* !< The transmitted data was
                                                                                    acknowledged */
#define M33C1SPGSS2_UC2_I2CC_IPSPECIFIC_SR_DATACK_SET ((uint32_t)0x00000008U)         /* !< The transmitted data was not
                                                                                    acknowledged. */
/* M33C1SPGSS2_UC2_I2CC_IPSPECIFIC_SR[ARBLST] Bits */
#define M33C1SPGSS2_UC2_I2CC_IPSPECIFIC_SR_ARBLST_OFS (4)                             /* !< ARBLST Offset */
#define M33C1SPGSS2_UC2_I2CC_IPSPECIFIC_SR_ARBLST_MASK ((uint32_t)0x00000010U)         /* !< Arbitration Lost */
#define M33C1SPGSS2_UC2_I2CC_IPSPECIFIC_SR_ARBLST_CLEARED ((uint32_t)0x00000000U)         /* !< The I2C controller won arbitration. */
#define M33C1SPGSS2_UC2_I2CC_IPSPECIFIC_SR_ARBLST_SET ((uint32_t)0x00000010U)         /* !< The I2C controller lost
                                                                                    arbitration. */
/* M33C1SPGSS2_UC2_I2CC_IPSPECIFIC_SR[IDLE] Bits */
#define M33C1SPGSS2_UC2_I2CC_IPSPECIFIC_SR_IDLE_OFS (5)                             /* !< IDLE Offset */
#define M33C1SPGSS2_UC2_I2CC_IPSPECIFIC_SR_IDLE_MASK ((uint32_t)0x00000020U)         /* !< I2C Idle */
#define M33C1SPGSS2_UC2_I2CC_IPSPECIFIC_SR_IDLE_CLEARED ((uint32_t)0x00000000U)         /* !< The I2C controller is not idle. */
#define M33C1SPGSS2_UC2_I2CC_IPSPECIFIC_SR_IDLE_SET ((uint32_t)0x00000020U)         /* !< The I2C controller is idle. */
/* M33C1SPGSS2_UC2_I2CC_IPSPECIFIC_SR[BUSBSY] Bits */
#define M33C1SPGSS2_UC2_I2CC_IPSPECIFIC_SR_BUSBSY_OFS (6)                             /* !< BUSBSY Offset */
#define M33C1SPGSS2_UC2_I2CC_IPSPECIFIC_SR_BUSBSY_MASK ((uint32_t)0x00000040U)         /* !< I2C Bus is Busy Controller State
                                                                                    Machine will wait until this bit to
                                                                                    be cleared before starting a
                                                                                    transaction. When first enabling the
                                                                                    Controller in multi Controller
                                                                                    environments, FW should wait for one
                                                                                    I2C clock period after setting ACTIVE
                                                                                    high before writing to the CTR
                                                                                    register to start the transaction so
                                                                                    that if SCL goes low it will trigger
                                                                                    the BUSBSY. */
#define M33C1SPGSS2_UC2_I2CC_IPSPECIFIC_SR_BUSBSY_CLEARED ((uint32_t)0x00000000U)         /* !< The I2C bus is idle. */
#define M33C1SPGSS2_UC2_I2CC_IPSPECIFIC_SR_BUSBSY_SET ((uint32_t)0x00000040U)         /* !< 'This Status bit is set on a START
                                                                                    or when SCL goes low. It is cleared
                                                                                    on a STOP,  or when a SCL high bus
                                                                                    busy timeout occurs and SCL and SDA
                                                                                    are both high. This status is cleared
                                                                                    when the ACTIVE bit is low. Note that
                                                                                    the Controller State Machine will
                                                                                    wait until this bit is cleared before
                                                                                    starting an I2C transaction. When
                                                                                    first enabling the Controller in
                                                                                    multi Controller environments, FW
                                                                                    should wait for one I2C clock period
                                                                                    after setting ACTIVE high before
                                                                                    writing to the MTCR register to start
                                                                                    the transaction so that if SCL goes
                                                                                    low it will trigger the BUSBSY. */
/* M33C1SPGSS2_UC2_I2CC_IPSPECIFIC_SR[RXCLR] Bits */
#define M33C1SPGSS2_UC2_I2CC_IPSPECIFIC_SR_RXCLR_OFS (9)                             /* !< RXCLR Offset */
#define M33C1SPGSS2_UC2_I2CC_IPSPECIFIC_SR_RXCLR_MASK ((uint32_t)0x00000200U)         /* !< RX FIFO Clear Status */
#define M33C1SPGSS2_UC2_I2CC_IPSPECIFIC_SR_RXCLR_CLEARED ((uint32_t)0x00000000U)         /* !< FIFO is not cleared */
#define M33C1SPGSS2_UC2_I2CC_IPSPECIFIC_SR_RXCLR_SET ((uint32_t)0x00000200U)         /* !< FIFO clear is complete */
/* M33C1SPGSS2_UC2_I2CC_IPSPECIFIC_SR[TXCLR] Bits */
#define M33C1SPGSS2_UC2_I2CC_IPSPECIFIC_SR_TXCLR_OFS (10)                            /* !< TXCLR Offset */
#define M33C1SPGSS2_UC2_I2CC_IPSPECIFIC_SR_TXCLR_MASK ((uint32_t)0x00000400U)         /* !< TX FIFO Clear Status */
#define M33C1SPGSS2_UC2_I2CC_IPSPECIFIC_SR_TXCLR_CLEARED ((uint32_t)0x00000000U)         /* !< FIFO is not cleared */
#define M33C1SPGSS2_UC2_I2CC_IPSPECIFIC_SR_TXCLR_SET ((uint32_t)0x00000400U)         /* !< FIFO clear is complete */
/* M33C1SPGSS2_UC2_I2CC_IPSPECIFIC_SR[RXFE] Bits */
#define M33C1SPGSS2_UC2_I2CC_IPSPECIFIC_SR_RXFE_OFS (11)                            /* !< RXFE Offset */
#define M33C1SPGSS2_UC2_I2CC_IPSPECIFIC_SR_RXFE_MASK ((uint32_t)0x00000800U)         /* !< Receive FIFO Empty  The meaning of
                                                                                    this bit depends on the state of the
                                                                                    FEN bit in the CTL0 register. */
#define M33C1SPGSS2_UC2_I2CC_IPSPECIFIC_SR_RXFE_CLEARED ((uint32_t)0x00000000U)         /* !< The receiver is not empty. */
#define M33C1SPGSS2_UC2_I2CC_IPSPECIFIC_SR_RXFE_SET ((uint32_t)0x00000800U)         /* !< If the FIFO is disabled (FEN is 0),
                                                                                    the receive holding register is
                                                                                    empty. If the FIFO is enabled (FEN is
                                                                                    1), the receive FIFO is empty. */
/* M33C1SPGSS2_UC2_I2CC_IPSPECIFIC_SR[RXFF] Bits */
#define M33C1SPGSS2_UC2_I2CC_IPSPECIFIC_SR_RXFF_OFS (12)                            /* !< RXFF Offset */
#define M33C1SPGSS2_UC2_I2CC_IPSPECIFIC_SR_RXFF_MASK ((uint32_t)0x00001000U)         /* !< Receive FIFO Full  The meaning of
                                                                                    this bit depends on the state of the
                                                                                    FEN bit in the CTL0 register. */
#define M33C1SPGSS2_UC2_I2CC_IPSPECIFIC_SR_RXFF_CLEARED ((uint32_t)0x00000000U)         /* !< The receiver can receive data. */
#define M33C1SPGSS2_UC2_I2CC_IPSPECIFIC_SR_RXFF_SET ((uint32_t)0x00001000U)         /* !< If the FIFO is disabled (FEN is 0),
                                                                                    the receive holding register is full.
                                                                                    If the FIFO is enabled (FEN is 1),
                                                                                    the receive FIFO is full. */
/* M33C1SPGSS2_UC2_I2CC_IPSPECIFIC_SR[TXFE] Bits */
#define M33C1SPGSS2_UC2_I2CC_IPSPECIFIC_SR_TXFE_OFS (13)                            /* !< TXFE Offset */
#define M33C1SPGSS2_UC2_I2CC_IPSPECIFIC_SR_TXFE_MASK ((uint32_t)0x00002000U)         /* !< Transmit FIFO Empty  The meaning of
                                                                                    this bit depends on the state of the
                                                                                    FEN bit in the CTL0 register. */
#define M33C1SPGSS2_UC2_I2CC_IPSPECIFIC_SR_TXFE_CLEARED ((uint32_t)0x00000000U)         /* !< The transmitter has data to
                                                                                    transmit. */
#define M33C1SPGSS2_UC2_I2CC_IPSPECIFIC_SR_TXFE_SET ((uint32_t)0x00002000U)         /* !< If the FIFO is disabled (FEN is 0),
                                                                                    the transmit holding register is
                                                                                    empty. If the FIFO is enabled (FEN is
                                                                                    1), the transmit FIFO is empty. */
/* M33C1SPGSS2_UC2_I2CC_IPSPECIFIC_SR[TXFF] Bits */
#define M33C1SPGSS2_UC2_I2CC_IPSPECIFIC_SR_TXFF_OFS (14)                            /* !< TXFF Offset */
#define M33C1SPGSS2_UC2_I2CC_IPSPECIFIC_SR_TXFF_MASK ((uint32_t)0x00004000U)         /* !< Transmit FIFO Full  The meaning of
                                                                                    this bit depends on the state of the
                                                                                    FEN bit in the CTL0 register. */
#define M33C1SPGSS2_UC2_I2CC_IPSPECIFIC_SR_TXFF_CLEARED ((uint32_t)0x00000000U)         /* !< The transmitter is not full. */
#define M33C1SPGSS2_UC2_I2CC_IPSPECIFIC_SR_TXFF_SET ((uint32_t)0x00004000U)         /* !< If the FIFO is disabled (FEN is 0),
                                                                                    the transmit holding register is
                                                                                    full. If the FIFO is enabled (FEN is
                                                                                    1), the transmit FIFO is full. */

