#define M33C1SPGSS2_UC3_UART_IPSPECIFIC_CTL0_ENABLE_MASK ((uint32_t)0x00000001U)         /* !< UART Module Enable.  If the UART is
                                                                                    disabled in the middle of
                                                                                    transmission or reception, it
                                                                                    completes the current character
                                                                                    before stopping.  If the ENABLE bit
                                                                                    is not set, all registers can still
                                                                                    be accessed and updated. It is
                                                                                    recommended to setup and change the
                                                                                    UART operation mode with having the
                                                                                    ENABLE bit cleared to avoid
                                                                                    unpredictable behavior during the
                                                                                    setup or update. If disabled the UART
                                                                                    module will not send or receive any
                                                                                    data and the logic is held in reset
                                                                                    state. */
#define M33C1SPGSS2_UC3_UART_IPSPECIFIC_CTL0_ENABLE_DISABLE ((uint32_t)0x00000000U)         /* !< Disable Module */
#define M33C1SPGSS2_UC3_UART_IPSPECIFIC_CTL0_ENABLE_ENABLE ((uint32_t)0x00000001U)         /* !< Enable module */
/* M33C1SPGSS2_UC3_UART_IPSPECIFIC_CTL0[HSE] Bits */
#define M33C1SPGSS2_UC3_UART_IPSPECIFIC_CTL0_HSE_OFS (15)                            /* !< HSE Offset */
#define M33C1SPGSS2_UC3_UART_IPSPECIFIC_CTL0_HSE_MASK ((uint32_t)0x00018000U)         /* !< High-Speed Bit Oversampling Enable
                                                                                    #b#NOTE:#/b# The bit oversampling
                                                                                    influences the UART baud-rate
                                                                                    configuration.  The state of this bit
                                                                                    has no effect on clock generation in
                                                                                    ISO7816 smart card mode (the SMART
                                                                                    bit is set). */
#define M33C1SPGSS2_UC3_UART_IPSPECIFIC_CTL0_HSE_OVS16 ((uint32_t)0x00000000U)         /* !< 16x oversampling. */
#define M33C1SPGSS2_UC3_UART_IPSPECIFIC_CTL0_HSE_OVS8 ((uint32_t)0x00008000U)         /* !< 8x oversampling. */
#define M33C1SPGSS2_UC3_UART_IPSPECIFIC_CTL0_HSE_OVS3 ((uint32_t)0x00010000U)         /* !< 3x oversampling. IrDA, Manchester
                                                                                    and DALI not supported when 3x
                                                                                    oversampling is enabled. */
/* M33C1SPGSS2_UC3_UART_IPSPECIFIC_CTL0[LBE] Bits */
#define M33C1SPGSS2_UC3_UART_IPSPECIFIC_CTL0_LBE_OFS (2)                             /* !< LBE Offset */
#define M33C1SPGSS2_UC3_UART_IPSPECIFIC_CTL0_LBE_MASK ((uint32_t)0x00000004U)         /* !< UART Loop Back Enable */
#define M33C1SPGSS2_UC3_UART_IPSPECIFIC_CTL0_LBE_DISABLE ((uint32_t)0x00000000U)         /* !< Normal operation. */
#define M33C1SPGSS2_UC3_UART_IPSPECIFIC_CTL0_LBE_ENABLE ((uint32_t)0x00000004U)         /* !< The UARTxTX path is fed through the
                                                                                    UARTxRX path internally. */
/* M33C1SPGSS2_UC3_UART_IPSPECIFIC_CTL0[RXE] Bits */
#define M33C1SPGSS2_UC3_UART_IPSPECIFIC_CTL0_RXE_OFS (3)                             /* !< RXE Offset */
#define M33C1SPGSS2_UC3_UART_IPSPECIFIC_CTL0_RXE_MASK ((uint32_t)0x00000008U)         /* !< UART Receive Enable  If the UART is
                                                                                    disabled in the middle of a receive,
                                                                                    it completes the current character
                                                                                    before stopping.   #b#NOTE:#/b# To
                                                                                    enable reception, the UARTEN bit must
                                                                                    be set. */
#define M33C1SPGSS2_UC3_UART_IPSPECIFIC_CTL0_RXE_DISABLE ((uint32_t)0x00000000U)         /* !< The receive section of the UART is
                                                                                    disabled. */
#define M33C1SPGSS2_UC3_UART_IPSPECIFIC_CTL0_RXE_ENABLE ((uint32_t)0x00000008U)         /* !< The receive section of the UART is
                                                                                    enabled. */
/* M33C1SPGSS2_UC3_UART_IPSPECIFIC_CTL0[TXE] Bits */
#define M33C1SPGSS2_UC3_UART_IPSPECIFIC_CTL0_TXE_OFS (4)                             /* !< TXE Offset */
#define M33C1SPGSS2_UC3_UART_IPSPECIFIC_CTL0_TXE_MASK ((uint32_t)0x00000010U)         /* !< UART Transmit Enable  If the UART
                                                                                    is disabled in the middle of a
                                                                                    transmission, it completes the
                                                                                    current character before stopping.
                                                                                    #b#NOTE:#/b# To enable transmission,
                                                                                    the UARTEN bit must be set. */
#define M33C1SPGSS2_UC3_UART_IPSPECIFIC_CTL0_TXE_DISABLE ((uint32_t)0x00000000U)         /* !< The transmit section of the UART is
                                                                                    disabled. The UARTxTXD pin of the
                                                                                    UART can be controlled by the TXD_CTL
                                                                                    bit when enabled. */
#define M33C1SPGSS2_UC3_UART_IPSPECIFIC_CTL0_TXE_ENABLE ((uint32_t)0x00000010U)         /* !< The transmit section of the UART is
                                                                                    enabled. */
/* M33C1SPGSS2_UC3_UART_IPSPECIFIC_CTL0[RTS] Bits */
#define M33C1SPGSS2_UC3_UART_IPSPECIFIC_CTL0_RTS_OFS (12)                            /* !< RTS Offset */
#define M33C1SPGSS2_UC3_UART_IPSPECIFIC_CTL0_RTS_MASK ((uint32_t)0x00001000U)         /* !< Request to Send    If RTSEN is set
                                                                                    the RTS output signals is controlled
                                                                                    by the hardware logic using the FIFO
                                                                                    fill level or buffer status.  If
                                                                                    RTSEN is cleared the RTS output is
                                                                                    controlled by the RTS bit. The bit is
                                                                                    the complement of the UART request to
                                                                                    send, RTS modem status output. */
#define M33C1SPGSS2_UC3_UART_IPSPECIFIC_CTL0_RTS_CLR ((uint32_t)0x00000000U)         /* !< Signal not RTS */
#define M33C1SPGSS2_UC3_UART_IPSPECIFIC_CTL0_RTS_SET ((uint32_t)0x00001000U)         /* !< Signal RTS */
/* M33C1SPGSS2_UC3_UART_IPSPECIFIC_CTL0[RTSEN] Bits */
#define M33C1SPGSS2_UC3_UART_IPSPECIFIC_CTL0_RTSEN_OFS (13)                            /* !< RTSEN Offset */
#define M33C1SPGSS2_UC3_UART_IPSPECIFIC_CTL0_RTSEN_MASK ((uint32_t)0x00002000U)         /* !< Enable hardware controlled Request
                                                                                    to Send */
#define M33C1SPGSS2_UC3_UART_IPSPECIFIC_CTL0_RTSEN_DISABLE ((uint32_t)0x00000000U)         /* !< RTS hardware flow control is
                                                                                    disabled. */
#define M33C1SPGSS2_UC3_UART_IPSPECIFIC_CTL0_RTSEN_ENABLE ((uint32_t)0x00002000U)         /* !< RTS hardware flow control is
                                                                                    enabled. Data is only requested (by
                                                                                    asserting UARTxRTS) when the receive
                                                                                    FIFO/buffer has available entries. */
/* M33C1SPGSS2_UC3_UART_IPSPECIFIC_CTL0[CTSEN] Bits */
#define M33C1SPGSS2_UC3_UART_IPSPECIFIC_CTL0_CTSEN_OFS (14)                            /* !< CTSEN Offset */
#define M33C1SPGSS2_UC3_UART_IPSPECIFIC_CTL0_CTSEN_MASK ((uint32_t)0x00004000U)         /* !< Enable Clear To Send */
#define M33C1SPGSS2_UC3_UART_IPSPECIFIC_CTL0_CTSEN_DISABLE ((uint32_t)0x00000000U)         /* !< CTS hardware flow control is
                                                                                    disabled. */
#define M33C1SPGSS2_UC3_UART_IPSPECIFIC_CTL0_CTSEN_ENABLE ((uint32_t)0x00004000U)         /* !< CTS hardware flow control is
                                                                                    enabled. Data is only transmitted
                                                                                    when the UARTxCTS signal is asserted. */
/* M33C1SPGSS2_UC3_UART_IPSPECIFIC_CTL0[MODE] Bits */
#define M33C1SPGSS2_UC3_UART_IPSPECIFIC_CTL0_MODE_OFS (8)                             /* !< MODE Offset */
#define M33C1SPGSS2_UC3_UART_IPSPECIFIC_CTL0_MODE_MASK ((uint32_t)0x00000700U)         /* !< Set the communication mode and
                                                                                    protocol used. (Not defined settings
                                                                                    uses the default setting: 0) */
#define M33C1SPGSS2_UC3_UART_IPSPECIFIC_CTL0_MODE_UART ((uint32_t)0x00000000U)         /* !< Normal operation */
#define M33C1SPGSS2_UC3_UART_IPSPECIFIC_CTL0_MODE_RS485 ((uint32_t)0x00000100U)         /* !< RS485 mode: UART needs to be IDLE
                                                                                    with receiving data for the in
                                                                                    EXTDIR_HOLD set time. EXTDIR_SETUP
                                                                                    defines the time the RTS line is set
                                                                                    to high before sending. When the
                                                                                    buffer is empty the RTS line is set
                                                                                    low again. A transmit will be delayed
                                                                                    as long the UART is receiving data. */
#define M33C1SPGSS2_UC3_UART_IPSPECIFIC_CTL0_MODE_IDLELINE ((uint32_t)0x00000200U)         /* !< The UART operates in IDLE Line Mode */
#define M33C1SPGSS2_UC3_UART_IPSPECIFIC_CTL0_MODE_ADDR9BIT ((uint32_t)0x00000300U)         /* !< The UART operates in 9 Bit Address
                                                                                    mode */
#define M33C1SPGSS2_UC3_UART_IPSPECIFIC_CTL0_MODE_SMART ((uint32_t)0x00000400U)         /* !< ISO7816 Smart Card Support  The
                                                                                    application must ensure that it sets
                                                                                    8-bit word length (WLEN set to 3h)
                                                                                    and even parity (PEN set to 1, EPS
                                                                                    set to 1, SPS set to 0) in UARTLCRH
                                                                                    when using ISO7816 mode. The value of
                                                                                    the STP2 bit in UARTLCRH is ignored
                                                                                    and the number of stop bits is forced
                                                                                    to 2. */
#define M33C1SPGSS2_UC3_UART_IPSPECIFIC_CTL0_MODE_DALI ((uint32_t)0x00000500U)         /* !< DALI Mode: */
/* M33C1SPGSS2_UC3_UART_IPSPECIFIC_CTL0[TXD_OUT] Bits */
#define M33C1SPGSS2_UC3_UART_IPSPECIFIC_CTL0_TXD_OUT_OFS (6)                             /* !< TXD_OUT Offset */
#define M33C1SPGSS2_UC3_UART_IPSPECIFIC_CTL0_TXD_OUT_MASK ((uint32_t)0x00000040U)         /* !< TXD Pin Control Controls the TXD
                                                                                    pin when TXD_OUT_EN = 1 and TXE = 0. */
#define M33C1SPGSS2_UC3_UART_IPSPECIFIC_CTL0_TXD_OUT_LOW ((uint32_t)0x00000000U)         /* !< TXD pin is low */
#define M33C1SPGSS2_UC3_UART_IPSPECIFIC_CTL0_TXD_OUT_HIGH ((uint32_t)0x00000040U)         /* !< TXD pin is high */
/* M33C1SPGSS2_UC3_UART_IPSPECIFIC_CTL0[TXD_OUT_EN] Bits */
#define M33C1SPGSS2_UC3_UART_IPSPECIFIC_CTL0_TXD_OUT_EN_OFS (5)                             /* !< TXD_OUT_EN Offset */
#define M33C1SPGSS2_UC3_UART_IPSPECIFIC_CTL0_TXD_OUT_EN_MASK ((uint32_t)0x00000020U)         /* !< TXD Pin Control Enable. When the
                                                                                    transmit section of the UART is
                                                                                    disabled (TXE = 0), the TXD pin can
                                                                                    be controlled by the TXD_OUT bit. */
#define M33C1SPGSS2_UC3_UART_IPSPECIFIC_CTL0_TXD_OUT_EN_DISABLE ((uint32_t)0x00000000U)         /* !< TXD pin can not be controlled by
                                                                                    TXD_OUT */
#define M33C1SPGSS2_UC3_UART_IPSPECIFIC_CTL0_TXD_OUT_EN_ENABLE ((uint32_t)0x00000020U)         /* !< TXD pin can be controlled by
                                                                                    TXD_OUT */
/* M33C1SPGSS2_UC3_UART_IPSPECIFIC_CTL0[MAJVOTE] Bits */
#define M33C1SPGSS2_UC3_UART_IPSPECIFIC_CTL0_MAJVOTE_OFS (18)                            /* !< MAJVOTE Offset */
#define M33C1SPGSS2_UC3_UART_IPSPECIFIC_CTL0_MAJVOTE_MASK ((uint32_t)0x00040000U)         /* !< Majority Vote Enable  When Majority
                                                                                    Voting is enabled, the three center
                                                                                    bits are used to determine received
                                                                                    sample value. In case of error (i.e.
                                                                                    all 3 bits are not the same), noise
                                                                                    error is detected and bits RIS.NERR
                                                                                    and register RXDATA.NERR are set.
                                                                                    Oversampling of 16 : bits 7, 8, 9
                                                                                    are used      Oversampling of 8 :
                                                                                    bits 3, 4, 5 are used Disabled :
                                                                                    Single sample value (center value)
                                                                                    used */
#define M33C1SPGSS2_UC3_UART_IPSPECIFIC_CTL0_MAJVOTE_DISABLE ((uint32_t)0x00000000U)         /* !< Majority voting is disabled */
#define M33C1SPGSS2_UC3_UART_IPSPECIFIC_CTL0_MAJVOTE_ENABLE ((uint32_t)0x00040000U)         /* !< Majority voting is enabled */
/* M33C1SPGSS2_UC3_UART_IPSPECIFIC_CTL0[MSBFIRST] Bits */
#define M33C1SPGSS2_UC3_UART_IPSPECIFIC_CTL0_MSBFIRST_OFS (19)                            /* !< MSBFIRST Offset */
#define M33C1SPGSS2_UC3_UART_IPSPECIFIC_CTL0_MSBFIRST_MASK ((uint32_t)0x00080000U)         /* !< Most Significant Bit First This bit
                                                                                    has effect both on the way protocol
                                                                                    byte is transmitted and received.
                                                                                    Notes: User needs to match the
                                                                                    protocol to the correct value of this
                                                                                    bit to send MSb or LSb first. The
                                                                                    hardware engine will send the byte
                                                                                    entirely based on this bit. */
#define M33C1SPGSS2_UC3_UART_IPSPECIFIC_CTL0_MSBFIRST_DISABLE ((uint32_t)0x00000000U)         /* !< Least significant bit is sent first
                                                                                    in the protocol packet */
#define M33C1SPGSS2_UC3_UART_IPSPECIFIC_CTL0_MSBFIRST_ENABLE ((uint32_t)0x00080000U)         /* !< Most significant bit is sent first
                                                                                    in the protocol packet */

/* M33C1SPGSS2_UC3_UART_IPSPECIFIC_LCRH Bits */
/* M33C1SPGSS2_UC3_UART_IPSPECIFIC_LCRH[BRK] Bits */
#define M33C1SPGSS2_UC3_UART_IPSPECIFIC_LCRH_BRK_OFS (0)                             /* !< BRK Offset */
#define M33C1SPGSS2_UC3_UART_IPSPECIFIC_LCRH_BRK_MASK ((uint32_t)0x00000001U)         /* !< UART Send Break (for LIN Protocol)
                                                                                    1. Break condition is sent on the
                                                                                    line for as long as this bit is set */
#define M33C1SPGSS2_UC3_UART_IPSPECIFIC_LCRH_BRK_DISABLE ((uint32_t)0x00000000U)         /* !< Normal operation */
#define M33C1SPGSS2_UC3_UART_IPSPECIFIC_LCRH_BRK_ENABLE ((uint32_t)0x00000001U)         /* !< A low level is continually output
                                                                                    on the UARTxTXD signal, after
                                                                                    completing transmission of the
                                                                                    current character. For the proper
                                                                                    execution of the break command,
                                                                                    software must set this bit for at
                                                                                    least two frames (character periods). */
/* M33C1SPGSS2_UC3_UART_IPSPECIFIC_LCRH[PEN] Bits */
#define M33C1SPGSS2_UC3_UART_IPSPECIFIC_LCRH_PEN_OFS (1)                             /* !< PEN Offset */
#define M33C1SPGSS2_UC3_UART_IPSPECIFIC_LCRH_PEN_MASK ((uint32_t)0x00000002U)         /* !< UART Parity Enable */
#define M33C1SPGSS2_UC3_UART_IPSPECIFIC_LCRH_PEN_DISABLE ((uint32_t)0x00000000U)         /* !< Parity is disabled and no parity
                                                                                    bit is added to the data frame. */
#define M33C1SPGSS2_UC3_UART_IPSPECIFIC_LCRH_PEN_ENABLE ((uint32_t)0x00000002U)         /* !< Parity checking and generation is
                                                                                    enabled. */
/* M33C1SPGSS2_UC3_UART_IPSPECIFIC_LCRH[EPS] Bits */
#define M33C1SPGSS2_UC3_UART_IPSPECIFIC_LCRH_EPS_OFS (2)                             /* !< EPS Offset */
#define M33C1SPGSS2_UC3_UART_IPSPECIFIC_LCRH_EPS_MASK ((uint32_t)0x00000004U)         /* !< UART Even Parity Select  This bit
                                                                                    has no effect when parity is disabled
                                                                                    by the PEN bit.  For 9-Bit UART Mode
                                                                                    transmissions, this bit controls the
                                                                                    address byte and data byte indication
                                                                                    (9th bit). 0 = The transferred byte
                                                                                    is a data byte 1 = The transferred
                                                                                    byte is an address byte */
#define M33C1SPGSS2_UC3_UART_IPSPECIFIC_LCRH_EPS_ODD ((uint32_t)0x00000000U)         /* !< Odd parity is performed, which
                                                                                    checks for an odd number of 1s. */
#define M33C1SPGSS2_UC3_UART_IPSPECIFIC_LCRH_EPS_EVEN ((uint32_t)0x00000004U)         /* !< Even parity generation and checking
                                                                                    is performed during transmission and
                                                                                    reception, which checks for an even
                                                                                    number of 1s in data and parity bits. */
/* M33C1SPGSS2_UC3_UART_IPSPECIFIC_LCRH[STP2] Bits */
#define M33C1SPGSS2_UC3_UART_IPSPECIFIC_LCRH_STP2_OFS (3)                             /* !< STP2 Offset */
#define M33C1SPGSS2_UC3_UART_IPSPECIFIC_LCRH_STP2_MASK ((uint32_t)0x00000008U)         /* !< UART Two Stop Bits Select     When
                                                                                    in 7816 smart card mode (the SMART
                                                                                    bit is set in the UARTCTL register),
                                                                                    the number of stop bits is forced to
                                                                                    2. */
#define M33C1SPGSS2_UC3_UART_IPSPECIFIC_LCRH_STP2_DISABLE ((uint32_t)0x00000000U)         /* !< One stop bit is transmitted at the
                                                                                    end of a frame. */
#define M33C1SPGSS2_UC3_UART_IPSPECIFIC_LCRH_STP2_ENABLE ((uint32_t)0x00000008U)         /* !< Two stop bits are transmitted at
                                                                                    the end of a frame. The receive logic
                                                                                    checks for two stop bits being
                                                                                    received and provide Frame Error if
                                                                                    either is invalid. */
/* M33C1SPGSS2_UC3_UART_IPSPECIFIC_LCRH[WLEN] Bits */
#define M33C1SPGSS2_UC3_UART_IPSPECIFIC_LCRH_WLEN_OFS (4)                             /* !< WLEN Offset */
#define M33C1SPGSS2_UC3_UART_IPSPECIFIC_LCRH_WLEN_MASK ((uint32_t)0x00000030U)         /* !< UART Word Length  The bits indicate
                                                                                    the number of data bits transmitted
                                                                                    or received in a frame as follows: */
#define M33C1SPGSS2_UC3_UART_IPSPECIFIC_LCRH_WLEN_DATABIT5 ((uint32_t)0x00000000U)         /* !< 5 bits (default) */
#define M33C1SPGSS2_UC3_UART_IPSPECIFIC_LCRH_WLEN_DATABIT6 ((uint32_t)0x00000010U)         /* !< 6 bits */
#define M33C1SPGSS2_UC3_UART_IPSPECIFIC_LCRH_WLEN_DATABIT7 ((uint32_t)0x00000020U)         /* !< 7 bits */
#define M33C1SPGSS2_UC3_UART_IPSPECIFIC_LCRH_WLEN_DATABIT8 ((uint32_t)0x00000030U)         /* !< 8 bits */
/* M33C1SPGSS2_UC3_UART_IPSPECIFIC_LCRH[SPS] Bits */
#define M33C1SPGSS2_UC3_UART_IPSPECIFIC_LCRH_SPS_OFS (6)                             /* !< SPS Offset */
#define M33C1SPGSS2_UC3_UART_IPSPECIFIC_LCRH_SPS_MASK ((uint32_t)0x00000040U)         /* !< UART Stick Parity Select The Stick
                                                                                    Parity Select (SPS) bit is used to
                                                                                    set either a permanent '1' or a
                                                                                    permanent '0' as parity when
                                                                                    transmitting or receiving data. Its
                                                                                    purpose is to typically indicate the
                                                                                    first byte of a package or to mark an
                                                                                    address byte, for example in a
                                                                                    multi-drop RS-485 network. When bits
                                                                                    PEN, EPS, and SPS of UARTLCRH are
                                                                                    set, the parity bit is transmitted
                                                                                    and checked as a 0.  When bits PEN
                                                                                    and SPS are set and EPS is cleared,
                                                                                    the parity bit is transmitted and
                                                                                    checked as a 1. */
#define M33C1SPGSS2_UC3_UART_IPSPECIFIC_LCRH_SPS_DISABLE ((uint32_t)0x00000000U)         /* !< Disable Stick Parity */
#define M33C1SPGSS2_UC3_UART_IPSPECIFIC_LCRH_SPS_ENABLE ((uint32_t)0x00000040U)         /* !< Enable Stick Parity */
/* M33C1SPGSS2_UC3_UART_IPSPECIFIC_LCRH[SENDIDLE] Bits */
#define M33C1SPGSS2_UC3_UART_IPSPECIFIC_LCRH_SENDIDLE_OFS (7)                             /* !< SENDIDLE Offset */
#define M33C1SPGSS2_UC3_UART_IPSPECIFIC_LCRH_SENDIDLE_MASK ((uint32_t)0x00000080U)         /* !< UART send IDLE pattern. When this
                                                                                    bit is set,  SENDIDLE period of 11
                                                                                    bit times will be sent on the TX
                                                                                    line.   Read STAT.SENDIDLE bit to
                                                                                    readback current status of SENDIDLE */
#define M33C1SPGSS2_UC3_UART_IPSPECIFIC_LCRH_SENDIDLE_DISABLE ((uint32_t)0x00000000U)         /* !< Normal operation */
#define M33C1SPGSS2_UC3_UART_IPSPECIFIC_LCRH_SENDIDLE_ENABLE ((uint32_t)0x00000080U)         /* !< Send Idle Pattern */
/* M33C1SPGSS2_UC3_UART_IPSPECIFIC_LCRH[EXTDIR_SETUP] Bits */
#define M33C1SPGSS2_UC3_UART_IPSPECIFIC_LCRH_EXTDIR_SETUP_OFS (16)                            /* !< EXTDIR_SETUP Offset */
#define M33C1SPGSS2_UC3_UART_IPSPECIFIC_LCRH_EXTDIR_SETUP_MASK ((uint32_t)0x001F0000U)         /* !< Defines the number of UARTclk ticks
                                                                                    the signal to control the external
                                                                                    driver for the RS485 will be set
                                                                                    before the START bit is send */
#define M33C1SPGSS2_UC3_UART_IPSPECIFIC_LCRH_EXTDIR_SETUP_MINIMUM ((uint32_t)0x00000000U)         /* !< Smallest value */
#define M33C1SPGSS2_UC3_UART_IPSPECIFIC_LCRH_EXTDIR_SETUP_MAXIMUM ((uint32_t)0x001F0000U)         /* !< Highest possible value */
/* M33C1SPGSS2_UC3_UART_IPSPECIFIC_LCRH[EXTDIR_HOLD] Bits */
#define M33C1SPGSS2_UC3_UART_IPSPECIFIC_LCRH_EXTDIR_HOLD_OFS (21)                            /* !< EXTDIR_HOLD Offset */
#define M33C1SPGSS2_UC3_UART_IPSPECIFIC_LCRH_EXTDIR_HOLD_MASK ((uint32_t)0x03E00000U)         /* !< Defines the number of UARTclk ticks
                                                                                    the signal to control the external
                                                                                    driver for the RS485 will be reset
                                                                                    after the beginning of the stop bit.
                                                                                    (If 2 STOP bits are enabled the
                                                                                    beginning of the 2nd STOP bit.) */
#define M33C1SPGSS2_UC3_UART_IPSPECIFIC_LCRH_EXTDIR_HOLD_MINIMUM ((uint32_t)0x00000000U)         /* !< Smallest value */
#define M33C1SPGSS2_UC3_UART_IPSPECIFIC_LCRH_EXTDIR_HOLD_MAXIMUM ((uint32_t)0x03E00000U)         /* !< Highest possible value */
/* M33C1SPGSS2_UC3_UART_IPSPECIFIC_LCRH[SUSPEND] Bits */
#define M33C1SPGSS2_UC3_UART_IPSPECIFIC_LCRH_SUSPEND_OFS (26)                            /* !< SUSPEND Offset */
#define M33C1SPGSS2_UC3_UART_IPSPECIFIC_LCRH_SUSPEND_MASK ((uint32_t)0x04000000U)         /* !< Suspend external communication */
#define M33C1SPGSS2_UC3_UART_IPSPECIFIC_LCRH_SUSPEND_DISABLE ((uint32_t)0x00000000U)         /* !< Functional mode resumed */
#define M33C1SPGSS2_UC3_UART_IPSPECIFIC_LCRH_SUSPEND_ENABLE ((uint32_t)0x04000000U)         /* !< External communication suspended */

/* M33C1SPGSS2_UC3_UART_IPSPECIFIC_STAT Bits */
/* M33C1SPGSS2_UC3_UART_IPSPECIFIC_STAT[BUSY] Bits */
#define M33C1SPGSS2_UC3_UART_IPSPECIFIC_STAT_BUSY_OFS (0)                             /* !< BUSY Offset */
#define M33C1SPGSS2_UC3_UART_IPSPECIFIC_STAT_BUSY_MASK ((uint32_t)0x00000001U)         /* !< UART Busy 			This bit is set as
                                                                                    soon as the transmit FIFO/buffer
                                                                                    becomes non-empty (regardless of
                                                                                    whether UART is enabled) or if a
                                                                                    receive data is currently ongoing
                                                                                    (after the start edge have been
                                                                                    detected until a complete byte,
                                                                                    including all stop bits, has been
                                                                                    received by the shift register). In
                                                                                    IDLE_Line mode the Busy signal also
                                                                                    stays set during the idle time
                                                                                    generation. */
#define M33C1SPGSS2_UC3_UART_IPSPECIFIC_STAT_BUSY_CLEARED ((uint32_t)0x00000000U)         /* !< The UART is not busy. */
#define M33C1SPGSS2_UC3_UART_IPSPECIFIC_STAT_BUSY_SET ((uint32_t)0x00000001U)         /* !< The UART is busy transmitting data.
                                                                                    This bit remains set until the
                                                                                    complete byte, including all stop
                                                                                    bits, has been sent/received
                                                                                    from/into the shift register. */
/* M33C1SPGSS2_UC3_UART_IPSPECIFIC_STAT[TXFF] Bits */
#define M33C1SPGSS2_UC3_UART_IPSPECIFIC_STAT_TXFF_OFS (6)                             /* !< TXFF Offset */
