/* M33C1SPGSS2_UC2_UART_IPSPECIFIC_CTL0 Bits */
/* M33C1SPGSS2_UC2_UART_IPSPECIFIC_CTL0[ENABLE] Bits */
#define M33C1SPGSS2_UC2_UART_IPSPECIFIC_CTL0_ENABLE_OFS (0)                             /* !< ENABLE Offset */
#define M33C1SPGSS2_UC2_UART_IPSPECIFIC_CTL0_ENABLE_MASK ((uint32_t)0x00000001U)         /* !< UART Module Enable.  If the UART is
                                                                                    disabled in the middle of
                                                                                    transmission or reception, it
                                                                                    completes the current character
                                                                                    before stopping.  If the ENABLE bit
                                                                                    is not set, all registers can still
                                                                                    be accessed and updated. It is
                                                                                    recommended to setup and change the
                                                                                    UART operation mode with having the
                                                                                    ENABLE bit cleared to avoid
                                                                                    unpredictable behavior during the
                                                                                    setup or update. If disabled the UART
                                                                                    module will not send or receive any
                                                                                    data and the logic is held in reset
                                                                                    state. */
#define M33C1SPGSS2_UC2_UART_IPSPECIFIC_CTL0_ENABLE_DISABLE ((uint32_t)0x00000000U)         /* !< Disable Module */
#define M33C1SPGSS2_UC2_UART_IPSPECIFIC_CTL0_ENABLE_ENABLE ((uint32_t)0x00000001U)         /* !< Enable module */
/* M33C1SPGSS2_UC2_UART_IPSPECIFIC_CTL0[HSE] Bits */
#define M33C1SPGSS2_UC2_UART_IPSPECIFIC_CTL0_HSE_OFS (15)                            /* !< HSE Offset */
#define M33C1SPGSS2_UC2_UART_IPSPECIFIC_CTL0_HSE_MASK ((uint32_t)0x00018000U)         /* !< High-Speed Bit Oversampling Enable
                                                                                    #b#NOTE:#/b# The bit oversampling
                                                                                    influences the UART baud-rate
                                                                                    configuration.  The state of this bit
                                                                                    has no effect on clock generation in
                                                                                    ISO7816 smart card mode (the SMART
                                                                                    bit is set). */
#define M33C1SPGSS2_UC2_UART_IPSPECIFIC_CTL0_HSE_OVS16 ((uint32_t)0x00000000U)         /* !< 16x oversampling. */
#define M33C1SPGSS2_UC2_UART_IPSPECIFIC_CTL0_HSE_OVS8 ((uint32_t)0x00008000U)         /* !< 8x oversampling. */
#define M33C1SPGSS2_UC2_UART_IPSPECIFIC_CTL0_HSE_OVS3 ((uint32_t)0x00010000U)         /* !< 3x oversampling. IrDA, Manchester
                                                                                    and DALI not supported when 3x
                                                                                    oversampling is enabled. */
/* M33C1SPGSS2_UC2_UART_IPSPECIFIC_CTL0[LBE] Bits */
#define M33C1SPGSS2_UC2_UART_IPSPECIFIC_CTL0_LBE_OFS (2)                             /* !< LBE Offset */
#define M33C1SPGSS2_UC2_UART_IPSPECIFIC_CTL0_LBE_MASK ((uint32_t)0x00000004U)         /* !< UART Loop Back Enable */
#define M33C1SPGSS2_UC2_UART_IPSPECIFIC_CTL0_LBE_DISABLE ((uint32_t)0x00000000U)         /* !< Normal operation. */
#define M33C1SPGSS2_UC2_UART_IPSPECIFIC_CTL0_LBE_ENABLE ((uint32_t)0x00000004U)         /* !< The UARTxTX path is fed through the
                                                                                    UARTxRX path internally. */
/* M33C1SPGSS2_UC2_UART_IPSPECIFIC_CTL0[RXE] Bits */
#define M33C1SPGSS2_UC2_UART_IPSPECIFIC_CTL0_RXE_OFS (3)                             /* !< RXE Offset */
#define M33C1SPGSS2_UC2_UART_IPSPECIFIC_CTL0_RXE_MASK ((uint32_t)0x00000008U)         /* !< UART Receive Enable  If the UART is
                                                                                    disabled in the middle of a receive,
                                                                                    it completes the current character
                                                                                    before stopping.   #b#NOTE:#/b# To
                                                                                    enable reception, the UARTEN bit must
                                                                                    be set. */
#define M33C1SPGSS2_UC2_UART_IPSPECIFIC_CTL0_RXE_DISABLE ((uint32_t)0x00000000U)         /* !< The receive section of the UART is
                                                                                    disabled. */
#define M33C1SPGSS2_UC2_UART_IPSPECIFIC_CTL0_RXE_ENABLE ((uint32_t)0x00000008U)         /* !< The receive section of the UART is
                                                                                    enabled. */
/* M33C1SPGSS2_UC2_UART_IPSPECIFIC_CTL0[TXE] Bits */
#define M33C1SPGSS2_UC2_UART_IPSPECIFIC_CTL0_TXE_OFS (4)                             /* !< TXE Offset */
#define M33C1SPGSS2_UC2_UART_IPSPECIFIC_CTL0_TXE_MASK ((uint32_t)0x00000010U)         /* !< UART Transmit Enable  If the UART
                                                                                    is disabled in the middle of a
                                                                                    transmission, it completes the
                                                                                    current character before stopping.
                                                                                    #b#NOTE:#/b# To enable transmission,
                                                                                    the UARTEN bit must be set. */
#define M33C1SPGSS2_UC2_UART_IPSPECIFIC_CTL0_TXE_DISABLE ((uint32_t)0x00000000U)         /* !< The transmit section of the UART is
                                                                                    disabled. The UARTxTXD pin of the
                                                                                    UART can be controlled by the TXD_CTL
                                                                                    bit when enabled. */
#define M33C1SPGSS2_UC2_UART_IPSPECIFIC_CTL0_TXE_ENABLE ((uint32_t)0x00000010U)         /* !< The transmit section of the UART is
                                                                                    enabled. */
/* M33C1SPGSS2_UC2_UART_IPSPECIFIC_CTL0[RTS] Bits */
#define M33C1SPGSS2_UC2_UART_IPSPECIFIC_CTL0_RTS_OFS (12)                            /* !< RTS Offset */
#define M33C1SPGSS2_UC2_UART_IPSPECIFIC_CTL0_RTS_MASK ((uint32_t)0x00001000U)         /* !< Request to Send    If RTSEN is set
                                                                                    the RTS output signals is controlled
                                                                                    by the hardware logic using the FIFO
                                                                                    fill level or buffer status.  If
                                                                                    RTSEN is cleared the RTS output is
                                                                                    controlled by the RTS bit. The bit is
                                                                                    the complement of the UART request to
                                                                                    send, RTS modem status output. */
#define M33C1SPGSS2_UC2_UART_IPSPECIFIC_CTL0_RTS_CLR ((uint32_t)0x00000000U)         /* !< Signal not RTS */
#define M33C1SPGSS2_UC2_UART_IPSPECIFIC_CTL0_RTS_SET ((uint32_t)0x00001000U)         /* !< Signal RTS */
/* M33C1SPGSS2_UC2_UART_IPSPECIFIC_CTL0[RTSEN] Bits */
#define M33C1SPGSS2_UC2_UART_IPSPECIFIC_CTL0_RTSEN_OFS (13)                            /* !< RTSEN Offset */
#define M33C1SPGSS2_UC2_UART_IPSPECIFIC_CTL0_RTSEN_MASK ((uint32_t)0x00002000U)         /* !< Enable hardware controlled Request
                                                                                    to Send */
#define M33C1SPGSS2_UC2_UART_IPSPECIFIC_CTL0_RTSEN_DISABLE ((uint32_t)0x00000000U)         /* !< RTS hardware flow control is
                                                                                    disabled. */
#define M33C1SPGSS2_UC2_UART_IPSPECIFIC_CTL0_RTSEN_ENABLE ((uint32_t)0x00002000U)         /* !< RTS hardware flow control is
                                                                                    enabled. Data is only requested (by
                                                                                    asserting UARTxRTS) when the receive
                                                                                    FIFO/buffer has available entries. */
/* M33C1SPGSS2_UC2_UART_IPSPECIFIC_CTL0[CTSEN] Bits */
#define M33C1SPGSS2_UC2_UART_IPSPECIFIC_CTL0_CTSEN_OFS (14)                            /* !< CTSEN Offset */
#define M33C1SPGSS2_UC2_UART_IPSPECIFIC_CTL0_CTSEN_MASK ((uint32_t)0x00004000U)         /* !< Enable Clear To Send */
#define M33C1SPGSS2_UC2_UART_IPSPECIFIC_CTL0_CTSEN_DISABLE ((uint32_t)0x00000000U)         /* !< CTS hardware flow control is
                                                                                    disabled. */
#define M33C1SPGSS2_UC2_UART_IPSPECIFIC_CTL0_CTSEN_ENABLE ((uint32_t)0x00004000U)         /* !< CTS hardware flow control is
                                                                                    enabled. Data is only transmitted
                                                                                    when the UARTxCTS signal is asserted. */
/* M33C1SPGSS2_UC2_UART_IPSPECIFIC_CTL0[MODE] Bits */
#define M33C1SPGSS2_UC2_UART_IPSPECIFIC_CTL0_MODE_OFS (8)                             /* !< MODE Offset */
#define M33C1SPGSS2_UC2_UART_IPSPECIFIC_CTL0_MODE_MASK ((uint32_t)0x00000700U)         /* !< Set the communication mode and
                                                                                    protocol used. (Not defined settings
                                                                                    uses the default setting: 0) */
#define M33C1SPGSS2_UC2_UART_IPSPECIFIC_CTL0_MODE_UART ((uint32_t)0x00000000U)         /* !< Normal operation */
#define M33C1SPGSS2_UC2_UART_IPSPECIFIC_CTL0_MODE_RS485 ((uint32_t)0x00000100U)         /* !< RS485 mode: UART needs to be IDLE
                                                                                    with receiving data for the in
                                                                                    EXTDIR_HOLD set time. EXTDIR_SETUP
                                                                                    defines the time the RTS line is set
                                                                                    to high before sending. When the
                                                                                    buffer is empty the RTS line is set
                                                                                    low again. A transmit will be delayed
                                                                                    as long the UART is receiving data. */
#define M33C1SPGSS2_UC2_UART_IPSPECIFIC_CTL0_MODE_IDLELINE ((uint32_t)0x00000200U)         /* !< The UART operates in IDLE Line Mode */
#define M33C1SPGSS2_UC2_UART_IPSPECIFIC_CTL0_MODE_ADDR9BIT ((uint32_t)0x00000300U)         /* !< The UART operates in 9 Bit Address
                                                                                    mode */
#define M33C1SPGSS2_UC2_UART_IPSPECIFIC_CTL0_MODE_SMART ((uint32_t)0x00000400U)         /* !< ISO7816 Smart Card Support  The
                                                                                    application must ensure that it sets
                                                                                    8-bit word length (WLEN set to 3h)
                                                                                    and even parity (PEN set to 1, EPS
                                                                                    set to 1, SPS set to 0) in UARTLCRH
                                                                                    when using ISO7816 mode. The value of
                                                                                    the STP2 bit in UARTLCRH is ignored
                                                                                    and the number of stop bits is forced
                                                                                    to 2. */
#define M33C1SPGSS2_UC2_UART_IPSPECIFIC_CTL0_MODE_DALI ((uint32_t)0x00000500U)         /* !< DALI Mode: */
/* M33C1SPGSS2_UC2_UART_IPSPECIFIC_CTL0[TXD_OUT] Bits */
#define M33C1SPGSS2_UC2_UART_IPSPECIFIC_CTL0_TXD_OUT_OFS (6)                             /* !< TXD_OUT Offset */
