#define M33C1SPGSS2_PINCM_U3_CTS_WUEN_NO_WAKEUP  ((uint32_t)0x00000000U)         /* !< Wake up not enabled */
#define M33C1SPGSS2_PINCM_U3_CTS_WUEN_WAKEUP     ((uint32_t)0x08000000U)         /* !< Wake up enabled */
/* M33C1SPGSS2_PINCM_U3_CTS[WCOMP] Bits */
