#define M33C1SPGSS2_PINCM_U3_CTS_WCOMP_MATCH_ZERO ((uint32_t)0x00000000U)         /* !< Match 0 will wake */
#define M33C1SPGSS2_PINCM_U3_CTS_WCOMP_MATCH_ONE ((uint32_t)0x10000000U)         /* !< Match 1 will wake */
/* M33C1SPGSS2_PINCM_U3_CTS[GFLT] Bits */
